-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance v1 (26 Nov 2026)
--  * Office staff can clock in at the office: no project needed. The phone's GPS must be
--    within the office radius (checked here in the database, so the page cannot be bypassed).
--  * Site staff clock in on a project as before (location recorded).
--  * The CEO sets the office location(s) and radius in Attendance → Office location.
--  * Clock-in / clock-out times are the server's time, not the phone's; hours are worked out here.
--  * One attendance record per person per day (India date).
-- Safe to run more than once.

create table if not exists office_locations (
  id          uuid default gen_random_uuid() primary key,
  name        text not null default 'Head office',
  lat         double precision not null check (lat between -90 and 90),
  lng         double precision not null check (lng between -180 and 180),
  radius_m    integer not null default 200 check (radius_m between 30 and 5000),
  active      boolean not null default true,
  created_by  uuid references profiles(id) on delete set null,
  created_at  timestamptz default now(),
  updated_at  timestamptz default now()
);
alter table office_locations enable row level security;
drop policy if exists "staff_read_offices" on office_locations;
create policy "staff_read_offices" on office_locations for select using (is_staff());
drop policy if exists "ceo_manage_offices" on office_locations;
create policy "ceo_manage_offices" on office_locations for all using (is_admin()) with check (is_admin());

alter table attendance add column if not exists work_type text not null default 'site';
alter table attendance drop constraint if exists attendance_work_type_check;
alter table attendance add constraint attendance_work_type_check check (work_type in ('office','site'));
alter table attendance add column if not exists office_location_id uuid references office_locations(id) on delete set null;
alter table attendance add column if not exists clock_in_accuracy_m numeric;
alter table attendance add column if not exists clock_in_distance_m numeric;
alter table attendance add column if not exists clock_out_accuracy_m numeric;
alter table attendance add column if not exists clock_out_distance_m numeric;
alter table attendance add column if not exists clock_out_address text;

-- One record per person per day (skipped with a notice if old duplicate rows exist)
do $$ begin
  create unique index if not exists attendance_one_per_day on attendance (employee_id, date);
exception when unique_violation then
  raise notice 'attendance_one_per_day not created: there are duplicate days to clean up first';
end $$;

-- Distance in metres between two GPS points
create or replace function geo_distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
returns double precision language sql immutable as $$
  select 2 * 6371000 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)));
$$;

create or replace function attendance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  ceo     boolean := auth.uid() is null or is_admin();   -- CEO or the server may correct records
  office  office_locations%rowtype;
  dist    double precision;
  slack   double precision;
begin
  if tg_op = 'INSERT' then
    if not ceo then
      new.date           := (now() at time zone 'Asia/Kolkata')::date;
      new.clock_in_time  := now();
      new.clock_out_time := null; new.clock_out_lat := null; new.clock_out_lng := null;
      new.total_hours    := null; new.overtime_hours := 0;
      new.attendance_status := 'present';
      new.is_location_mismatch := false;
    end if;

    if new.work_type = 'office' then
      new.project_id := null;
      if new.clock_in_lat is null or new.clock_in_lng is null then
        raise exception 'Your location is needed to clock in at the office.';
      end if;
      select * into office from office_locations where active
        order by geo_distance_m(lat, lng, new.clock_in_lat::float8, new.clock_in_lng::float8) limit 1;
      if not found then
        raise exception 'The office location has not been set yet. Ask the CEO to set it in Attendance → Office location.';
      end if;
      dist := geo_distance_m(office.lat, office.lng, new.clock_in_lat::float8, new.clock_in_lng::float8);
      new.office_location_id  := office.id;
      new.clock_in_distance_m := round(dist::numeric);
      -- Indoor GPS is rough: allow the reported accuracy on top of the radius, up to 100 m
      slack := least(coalesce(new.clock_in_accuracy_m::float8, 0), 100);
      if dist > office.radius_m + slack and not ceo then
        raise exception 'You are about % m from %. Office clock-in works within % m. Go to the office (or near a window / outside for a better GPS signal) and try again.',
          round(dist::numeric), office.name, office.radius_m;
      end if;
    elsif new.project_id is null and not ceo then
      raise exception 'Choose the project / site you are working at.';
    end if;
    return new;
  end if;

  -- UPDATE
  if not ceo then
    if old.clock_out_time is not null then
      raise exception 'You have already clocked out today.';
    end if;
    -- Staff may only add their clock-out; everything about the clock-in stays as recorded
    new.employee_id := old.employee_id; new.date := old.date; new.work_type := old.work_type;
    new.project_id := old.project_id; new.office_location_id := old.office_location_id;
    new.clock_in_time := old.clock_in_time; new.clock_in_lat := old.clock_in_lat; new.clock_in_lng := old.clock_in_lng;
    new.clock_in_address := old.clock_in_address; new.clock_in_accuracy_m := old.clock_in_accuracy_m;
    new.clock_in_distance_m := old.clock_in_distance_m; new.attendance_status := old.attendance_status;
    if new.clock_out_time is not null then new.clock_out_time := now(); end if;
  end if;

  if new.clock_out_time is not null and new.work_type = 'office' and new.clock_out_lat is not null and new.clock_out_lng is not null then
    select * into office from office_locations where id = new.office_location_id;
    if found then
      dist := geo_distance_m(office.lat, office.lng, new.clock_out_lat::float8, new.clock_out_lng::float8);
      new.clock_out_distance_m := round(dist::numeric);
      -- Clock-out is never blocked; leaving from somewhere else is flagged for the CEO
      new.is_location_mismatch := dist > office.radius_m + least(coalesce(new.clock_out_accuracy_m::float8, 0), 100);
    end if;
  end if;

  if new.clock_out_time is not null and new.clock_in_time is not null then
    new.total_hours    := round((extract(epoch from new.clock_out_time - new.clock_in_time) / 3600)::numeric, 2);
    new.overtime_hours := greatest(0, new.total_hours - 8);
  end if;
  return new;
end;$$;

drop trigger if exists trg_attendance_guard on attendance;
create trigger trg_attendance_guard before insert or update on attendance
  for each row execute function attendance_guard();


-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_devices_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance trusted phones v1 (26 Nov 2026)
--  * Each staff member registers ONE mobile phone; the CEO approves it.
--  * Clock-in / clock-out only work from that approved phone, and only from a mobile browser.
--  * Staff can no longer write attendance rows directly: everything goes through
--    attendance_clock_in / attendance_clock_out, which check the phone, then the office GPS rules
--    (attendance_v1.sql) still apply.
--  * The CEO does not clock in or out (manages attendance; can still correct records).
-- The phone keeps a random secret; only its SHA-256 is stored here.
-- Needs attendance_v1.sql first. Safe to run more than once.

create table if not exists trusted_devices (
  id           uuid default gen_random_uuid() primary key,
  employee_id  uuid not null references profiles(id) on delete cascade,
  secret_hash  text not null,
  label        text,
  user_agent   text,
  status       text not null default 'pending' check (status in ('pending','approved','rejected','revoked')),
  created_at   timestamptz default now(),
  decided_by   uuid references profiles(id) on delete set null,
  decided_at   timestamptz,
  last_used_at timestamptz
);
create index if not exists trusted_devices_employee on trusted_devices (employee_id, status);
alter table trusted_devices enable row level security;
drop policy if exists "read_trusted_devices" on trusted_devices;
create policy "read_trusted_devices" on trusted_devices for select using (employee_id = auth.uid() or is_manager());
-- No insert / update / delete policies: only the functions below change this table.

alter table attendance add column if not exists device_id uuid references trusted_devices(id) on delete set null;

-- Staff no longer insert or edit attendance directly (the CEO's correction policy stays)
drop policy if exists "Employee clock in/out" on attendance;
drop policy if exists "Employee update own" on attendance;

create or replace function _sha256_hex(t text) returns text language sql immutable as $$
  select encode(sha256(convert_to(t, 'UTF8')), 'hex');
$$;

-- Browser of the current request (PostgREST passes the request headers)
create or replace function _request_is_mobile() returns boolean language plpgsql stable as $$
declare ua text;
begin
  begin ua := coalesce(current_setting('request.headers', true)::json->>'user-agent', '');
  exception when others then ua := ''; end;
  return ua ~* '(android|iphone|ipod|mobile)' and ua !~* '(ipad|tablet)';
end;$$;

create or replace function _request_user_agent() returns text language plpgsql stable as $$
begin
  return left(coalesce(current_setting('request.headers', true)::json->>'user-agent', ''), 400);
exception when others then return ''; end;$$;

-- Staff: ask to make this phone the trusted one
create or replace function register_attendance_device(p_secret text, p_label text)
returns uuid language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); new_id uuid; who text;
begin
  if uid is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if length(coalesce(p_secret, '')) < 32 then raise exception 'Invalid device code.'; end if;
  if not _request_is_mobile() then
    raise exception 'Register from your mobile phone: open the CRM on the phone you will carry to work.';
  end if;
  -- An earlier, still-waiting request is replaced by this one
  update trusted_devices set status = 'rejected', decided_at = now()
    where employee_id = uid and status = 'pending';
  insert into trusted_devices (employee_id, secret_hash, label, user_agent)
    values (uid, _sha256_hex(p_secret), left(coalesce(nullif(trim(p_label), ''), 'Mobile phone'), 80), _request_user_agent())
    returning id into new_id;
  select full_name into who from profiles where id = uid;
  insert into notifications (user_id, type, title, message, link)
    select id, 'attendance', 'Phone waiting for approval',
           coalesce(who, 'A staff member') || ' registered a phone for attendance: ' || coalesce(p_label, 'Mobile phone'), '/staff/attendance'
    from profiles where role = 'admin' and status = 'active';
  return new_id;
end;$$;

-- CEO: approve, reject or revoke. Approving one phone revokes that person's other phones.
create or replace function decide_attendance_device(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
declare d trusted_devices%rowtype;
begin
  if not is_admin() then raise exception 'Only the CEO can approve phones.'; end if;
  if p_status not in ('approved','rejected','revoked') then raise exception 'Unknown status.'; end if;
  select * into d from trusted_devices where id = p_id;
  if not found then raise exception 'Phone not found.'; end if;
  if p_status = 'approved' then
    update trusted_devices set status = 'revoked', decided_by = auth.uid(), decided_at = now()
      where employee_id = d.employee_id and id <> d.id and status in ('approved','pending');
  end if;
  update trusted_devices set status = p_status, decided_by = auth.uid(), decided_at = now() where id = p_id;
  insert into notifications (user_id, type, title, message, link) values (d.employee_id, 'attendance',
    case p_status when 'approved' then 'Your phone is approved for attendance' else 'Your attendance phone was not approved' end,
    case p_status when 'approved' then 'You can now clock in and out from ' || coalesce(d.label, 'your phone') || '.'
         else 'Contact the CEO, or register your phone again.' end,
    '/staff/attendance');
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'attendance_device_' || p_status, 'trusted_devices', p_id,
            'Attendance phone "' || coalesce(d.label, '') || '" ' || p_status);
end;$$;

-- Checks the phone; returns its id (null for the CEO without a phone)
create or replace function _check_attendance_device(p_device uuid, p_secret text)
returns uuid language plpgsql security definer set search_path = public as $$
declare d trusted_devices%rowtype;
begin
  select * into d from trusted_devices
    where id = p_device and employee_id = auth.uid() and status = 'approved'
      and secret_hash = _sha256_hex(coalesce(p_secret, ''));
  if found then
    if not _request_is_mobile() and not is_admin() then
      raise exception 'Attendance can only be marked from your mobile phone.';
    end if;
    update trusted_devices set last_used_at = now() where id = d.id;
    return d.id;
  end if;
  if is_admin() then return null; end if;
  if not _request_is_mobile() then raise exception 'Attendance can only be marked from your mobile phone.'; end if;
  raise exception 'This phone is not your approved attendance phone. Register it on the Attendance page and ask the CEO to approve it.';
end;$$;

create or replace function attendance_clock_in(
  p_device uuid, p_secret text, p_work_type text, p_project uuid,
  p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare dev uuid; new_id uuid;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if is_admin() then raise exception 'The CEO does not clock in or out.'; end if;
  dev := _check_attendance_device(p_device, p_secret);
  if exists (select 1 from attendance where employee_id = auth.uid() and date = (now() at time zone 'Asia/Kolkata')::date) then
    raise exception 'You have already clocked in today.';
  end if;
  if p_work_type = 'site' and p_project is not null and not is_manager() and not exists (
    select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null) then
    raise exception 'You are not assigned to that project.';
  end if;
  -- attendance_guard (attendance_v1.sql) sets the time and date and checks the office distance
  insert into attendance (employee_id, work_type, project_id, clock_in_lat, clock_in_lng, clock_in_accuracy_m, clock_in_address, device_id)
    values (auth.uid(), case when p_work_type = 'office' then 'office' else 'site' end, p_project,
            p_lat, p_lng, p_accuracy, left(p_address, 500), dev)
    returning id into new_id;
  return new_id;
end;$$;

create or replace function attendance_clock_out(
  p_device uuid, p_secret text, p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare rec_id uuid;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  perform _check_attendance_device(p_device, p_secret);
  select id into rec_id from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time is not null
    order by clock_in_time desc limit 1;
  if rec_id is null then raise exception 'You are not clocked in.'; end if;
  update attendance set clock_out_time = now(), clock_out_lat = p_lat, clock_out_lng = p_lng,
         clock_out_accuracy_m = p_accuracy, clock_out_address = left(p_address, 500)
    where id = rec_id;
  return rec_id;
end;$$;

revoke all on function register_attendance_device(text, text), decide_attendance_device(uuid, text),
  _check_attendance_device(uuid, text),
  attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) from public, anon;
grant execute on function register_attendance_device(text, text), decide_attendance_device(uuid, text),
  attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ quotation_allocation_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Quotation work allocation v1 (26 Nov 2026)
-- The CEO / admin manager gives each enquiry to up to three people (any staff, or the same person):
--   1. Site visit & customer meeting  → assigned_engineer_id
--   2. Prepares the quotation         → assigned_sales_id
--   3. Follows up with the customer   → follow_up_manager_id
-- and the CEO approves (unchanged). Each person can do their own part, and only that:
--   * the site-visit person records the visit (date, notes, roof / bill details, GPS at the site);
--   * the follow-up person shares the approved quotation, logs calls, marks hot / cold, accepted or lost;
--   * prices stay with the preparer (and the CEO / admin manager).
-- Everyone gets an in-app notification when work is given to them.
-- Safe to run more than once.

alter table quotation_requests add column if not exists site_visit_at      timestamptz;   -- planned date & time
alter table quotation_requests add column if not exists site_visit_done_at timestamptz;
alter table quotation_requests add column if not exists site_visit_notes   text;
alter table quotation_requests add column if not exists site_visit_lat     double precision;
alter table quotation_requests add column if not exists site_visit_lng     double precision;

-- Any of the three people may update the quotation (what they may change is checked below)
drop policy if exists "sales_update_assigned" on quotation_requests;
create policy "sales_update_assigned" on quotation_requests for update
  using (is_staff() and auth.uid() in (assigned_sales_id, assigned_engineer_id, follow_up_manager_id))
  with check (auth.uid() in (assigned_sales_id, assigned_engineer_id, follow_up_manager_id) or is_manager() or can_manage_quotations());

create or replace function quotation_role_guard()
returns trigger language plpgsql set search_path = public as $$
declare
  uid     uuid := auth.uid();
  visitor boolean;
  fu      boolean;
  allowed text[] := array['updated_at', 'next_follow_up_date', 'follow_up_count', 'lead_temperature', 'lead_temperature_note', 'lead_temperature_at'];
  move    text := old.status || '>' || new.status;
begin
  -- Server, CEO, admin manager, delegated staff and the preparer: the main rules (quotation_guard) apply
  if uid is null or is_manager() or can_manage_quotations() or old.assigned_sales_id = uid
     or coalesce(current_setting('greenergy.converting', true), '') = 'on' then
    return new;
  end if;
  visitor := old.assigned_engineer_id = uid;
  fu      := old.follow_up_manager_id = uid;
  if visitor then
    allowed := allowed || array['status', 'site_visit_at', 'site_visit_done_at', 'site_visit_notes', 'site_visit_lat', 'site_visit_lng',
      'address', 'city', 'eb_consumer_number', 'sanctioned_load_kw', 'avg_monthly_units', 'avg_monthly_bill', 'roof_type',
      'available_roof_area_sqft', 'current_phase', 'notes', 'roof_photo_url', 'eb_bill_url'];
  end if;
  if fu then
    allowed := allowed || array['status', 'sent_to_customer_at', 'accepted_by_name', 'accepted_via', 'accepted_note',
      'customer_response_at', 'lost_reason'];
  end if;
  if (to_jsonb(new) - allowed) is distinct from (to_jsonb(old) - allowed) then
    raise exception '%', case
      when visitor and fu then 'You can update the site visit and the follow-up of this quotation. Prices are changed by the person preparing it.'
      when visitor then 'You can update the site visit of this quotation. The quotation itself is prepared by someone else.'
      else 'You can follow up this quotation. Changes to it are made by the person preparing it.' end;
  end if;
  if new.status is distinct from old.status and not (
       (visitor and old.status in ('new', 'sales_review', 'site_details_pending', 'site_visit_scheduled')
                and new.status in ('site_visit_scheduled', 'site_visit_done'))
    or (fu and move in ('approved>sent_to_customer', 'sent_to_customer>customer_accepted', 'customer_accepted>advance_pending',
                        'sent_to_customer>cancelled', 'customer_accepted>cancelled', 'advance_pending>cancelled'))) then
    raise exception 'This step is done by the person preparing the quotation, the admin manager or the CEO.';
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_role_guard on quotation_requests;
create trigger trg_quotation_role_guard before update on quotation_requests
  for each row execute function quotation_role_guard();

-- Tell people when work is given to them, and pass the baton along the way
create or replace function quotation_assign_notify()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_link text := '/staff/quotations/' || new.id;
  v_who  text := coalesce(new.customer_name, 'customer') || ' · ' || coalesce(new.quotation_number, '')
                 || coalesce(' · ' || new.city, '') || coalesce(' · ' || new.mobile, '');
  v_by   text := coalesce(my_name(), 'The CEO');
  me     uuid := auth.uid();
  o      quotation_requests%rowtype;
begin
  if tg_op = 'UPDATE' then o := old; end if;
  if new.assigned_engineer_id is not null and new.assigned_engineer_id is distinct from o.assigned_engineer_id and new.assigned_engineer_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.assigned_engineer_id, 'quotation',
      'Site visit given to you', v_who || coalesce(' · visit ' || to_char(new.site_visit_at at time zone 'Asia/Kolkata', 'DD Mon, HH12:MI AM'), '') || ' · by ' || v_by, v_link);
  end if;
  if new.assigned_sales_id is not null and new.assigned_sales_id is distinct from o.assigned_sales_id and new.assigned_sales_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.assigned_sales_id, 'quotation',
      'Quotation to prepare', v_who || ' · by ' || v_by, v_link);
  end if;
  if new.follow_up_manager_id is not null and new.follow_up_manager_id is distinct from o.follow_up_manager_id and new.follow_up_manager_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.follow_up_manager_id, 'quotation',
      'Customer follow-up given to you', v_who || ' · by ' || v_by, v_link);
  end if;
  if tg_op = 'UPDATE' then
    -- Visit date changed
    if new.site_visit_at is distinct from old.site_visit_at and new.site_visit_at is not null
       and new.assigned_engineer_id is not null and new.assigned_engineer_id is not distinct from old.assigned_engineer_id
       and new.assigned_engineer_id is distinct from me then
      insert into notifications (user_id, type, title, message, link) values (new.assigned_engineer_id, 'quotation',
        'Site visit date set', v_who || ' · ' || to_char(new.site_visit_at at time zone 'Asia/Kolkata', 'DD Mon, HH12:MI AM'), v_link);
    end if;
    -- Visit done → the preparer can start
    if new.site_visit_done_at is not null and old.site_visit_done_at is null
       and new.assigned_sales_id is not null and new.assigned_sales_id is distinct from me then
      insert into notifications (user_id, type, title, message, link) values (new.assigned_sales_id, 'quotation',
        'Site visit done — prepare the quotation', v_who, v_link);
    end if;
    -- Approved → the follow-up person can share it
    if new.status = 'approved' and old.status <> 'approved' and new.follow_up_manager_id is not null
       and new.follow_up_manager_id is distinct from new.assigned_sales_id then
      insert into notifications (user_id, type, title, message, link) values (new.follow_up_manager_id, 'quotation',
        'Quotation approved — ready to share with the customer', v_who, v_link);
    end if;
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_assign_notify on quotation_requests;
create trigger trg_quotation_assign_notify after insert or update on quotation_requests
  for each row execute function quotation_assign_notify();


-- ┌───────────────────────────────────────────────────────────────
-- │ lead_temperature_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Lead hot / cold v1 (26 Nov 2026)
--  * Hot / cold can be set at any stage, from the first enquiry (before only after sharing),
--    by the CEO, admin manager or any of the people working on the quotation.
--  * When it changes, the time and a short reason are kept; history shows who changed it.
--  * Logging a follow-up with hot / cold updates the quotation at any open stage.
-- Replaces quotation_guard() and follow_up_sync() from workflow_v2.sql. Safe to run more than once.

alter table quotation_requests add column if not exists lead_temperature_at   timestamptz;
alter table quotation_requests add column if not exists lead_temperature_note text;

create or replace function quotation_guard()
returns trigger language plpgsql set search_path = public as $$
declare
  v_uid   uuid := auth.uid();
  v_role  text;
  v_from  text := old.status;
  v_to    text := new.status;
  v_move  text := old.status || '>' || new.status;
  v_conv  boolean := coalesce(current_setting('greenergy.converting', true), '') = 'on';
begin
  -- Server-side service calls (public form, customer portal) and the SQL editor run without a user
  if v_uid is null then
    if v_to = 'customer_accepted' and v_from <> 'customer_accepted' and new.customer_response_at is null then
      new.customer_response_at := now();
    end if;
    return new;
  end if;

  v_role := my_role();
  if v_role is null then raise exception 'Your staff account is not active.'; end if;

  if v_from = 'project_created' and not v_conv then
    raise exception 'This quotation has a job card (%) and is locked.', old.job_number;
  end if;

  -- Job-card number and project link only come from convert_quotation_to_project()
  if not v_conv and (new.job_number is distinct from old.job_number or new.project_id is distinct from old.project_id
                     or new.converted_at is distinct from old.converted_at or new.converted_by is distinct from old.converted_by) then
    raise exception 'Job card numbers are issued only by "Create job card".';
  end if;
  if not v_conv and v_to = 'project_created' then
    raise exception 'Use "Create job card" to convert an accepted, hot quotation.';
  end if;

  -- Only managers reassign people
  if v_role = 'employee' and (new.assigned_sales_id is distinct from old.assigned_sales_id
       or new.assigned_engineer_id is distinct from old.assigned_engineer_id
       or new.follow_up_manager_id is distinct from old.follow_up_manager_id) then
    raise exception 'Only the CEO or admin manager can reassign a quotation.';
  end if;

  -- Stage moves
  if v_from <> v_to then
    if quotation_editable(v_from) and (quotation_editable(v_to) or v_to = 'owner_approval_pending') then
      null;                                                     -- prepare / submit for approval
    elsif v_from = 'owner_approval_pending' and v_to in ('approved','more_info_requested','rejected') then
      if v_role <> 'admin' then raise exception 'Only the CEO can approve, reject or send back a quotation.'; end if;
    elsif v_from = 'owner_approval_pending' and v_to = 'drafted' then
      null;                                                     -- withdrawn or sent back for changes
    elsif v_move in ('approved>sent_to_customer','sent_to_customer>customer_accepted','customer_accepted>advance_pending') then
      null;
    elsif v_from in ('approved','sent_to_customer','customer_accepted','advance_pending') and v_to = 'drafted' then
      -- Revision: approval is cleared and the old customer link stops working
      new.revision         := old.revision + 1;
      new.approved_by      := null;
      new.approved_by_name := null;
      new.approved_at      := null;
      new.portal_token     := uuid_generate_v4();
    elsif v_from in ('sent_to_customer','customer_accepted','advance_pending') and v_to = 'cancelled' then
      null;                                                     -- lost / declined
    elsif quotation_editable(v_from) and v_to in ('cancelled','rejected') then
      if v_role = 'employee' then raise exception 'Only the CEO or admin manager can close this quotation.'; end if;
    elsif v_from in ('cancelled','rejected') and v_to = 'drafted' then
      if v_role = 'employee' then raise exception 'Only the CEO or admin manager can reopen a quotation.'; end if;
    elsif v_to = 'project_created' and v_conv then
      null;
    else
      raise exception 'A quotation cannot move from "%" to "%".', v_from, v_to;
    end if;
  end if;

  -- Approval is stamped by the database, never by the client
  if v_to = 'approved' and v_from <> 'approved' then
    new.approved_by      := v_uid;
    new.approved_by_name := my_name();
    new.approved_at      := now();
    new.reviewed_by      := v_uid;
    new.reviewed_at      := now();
  elsif v_to = 'approved' and (new.approved_by is distinct from old.approved_by or new.approved_at is distinct from old.approved_at) then
    raise exception 'Approval details cannot be edited.';
  elsif v_to <> 'approved' and v_from = v_to and (new.approved_by is distinct from old.approved_by) then
    raise exception 'Approval details cannot be edited.';
  end if;

  -- Prices and scope change only while editable (a revision makes it editable again)
  if not (quotation_editable(v_to) or (quotation_editable(v_from) and v_to = 'owner_approval_pending')) and (
       new.admin_capacity_kw is distinct from old.admin_capacity_kw or new.admin_system_cost is distinct from old.admin_system_cost
    or new.admin_gst_amount  is distinct from old.admin_gst_amount  or new.admin_total_cost  is distinct from old.admin_total_cost
    or new.admin_subsidy     is distinct from old.admin_subsidy     or new.admin_net_cost    is distinct from old.admin_net_cost
    or new.central_subsidy   is distinct from old.central_subsidy   or new.state_subsidy     is distinct from old.state_subsidy
    or new.price_per_kw      is distinct from old.price_per_kw      or new.discount          is distinct from old.discount
    or new.region            is distinct from old.region            or new.panel_type        is distinct from old.panel_type
    or new.solar_type        is distinct from old.solar_type        or new.consumer_type     is distinct from old.consumer_type
    or new.valid_until       is distinct from old.valid_until) then
    raise exception 'Prices are locked after approval. Use "Revise" — the CEO must approve the new version.';
  end if;

  -- Hot / cold can be set at any stage (from the first enquiry), but not on a closed quotation
  if new.lead_temperature is distinct from old.lead_temperature
     and v_to in ('cancelled','rejected','project_created') and not v_conv then
    raise exception 'Hot / cold cannot be changed on a closed quotation.';
  end if;

  if v_to = 'sent_to_customer' and v_from <> 'sent_to_customer' then
    new.sent_to_customer_at := now();
    if new.next_follow_up_date is null or new.next_follow_up_date < current_date then
      new.next_follow_up_date := current_date + 1;
    end if;
  end if;
  if v_to = 'customer_accepted' and v_from <> 'customer_accepted' then
    new.customer_response_at := coalesce(new.customer_response_at, now());
    new.accepted_via := coalesce(new.accepted_via, 'staff');
  end if;
  return new;
end;$$;

create or replace function follow_up_sync()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update quotation_requests
     set next_follow_up_date = new.next_follow_up_date,
         follow_up_count     = follow_up_count + 1,
         lead_temperature    = coalesce(new.temperature, lead_temperature),
         lead_temperature_note = case when new.temperature is not null then left(new.notes, 300) else lead_temperature_note end
   where id = new.quotation_id and status not in ('project_created','cancelled','rejected');
  return new;
end;$$;

-- Stamp when the temperature changed (runs after the permission checks)
create or replace function quotation_temperature_stamp()
returns trigger language plpgsql as $$
begin
  if new.lead_temperature is distinct from old.lead_temperature then
    new.lead_temperature_at := case when new.lead_temperature is null then null else now() end;
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_temp_stamp on quotation_requests;
create trigger trg_quotation_temp_stamp before update on quotation_requests
  for each row execute function quotation_temperature_stamp();


-- ┌───────────────────────────────────────────────────────────────
-- │ job_card_ongoing_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Job cards for ongoing projects v1 (26 Nov 2026)
-- Projects that started before the CRM (or were added without a quotation) can get a numbered
-- job card (GSS/JC/<FY>/<n>, same series as converted quotations), with:
--   * the cradle-to-grave milestones, those already finished marked done and the current one in progress;
--   * the payment schedule as an opening balance: amount already received (paid) + balance due;
--   * an optional old / paper job card reference.
-- Either for an existing project record, or a new ongoing project entered in one step.
-- CEO and admin manager only. Safe to run more than once.

alter table projects add column if not exists legacy_ref text;   -- old / paper job card number, if any
alter table projects add column if not exists onboarded_at timestamptz;  -- when an ongoing project got its CRM job card

-- The job number may only be set by the CRM's own functions
create or replace function project_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if auth.uid() is null or coalesce(current_setting('greenergy.converting', true), '') = 'on' then return new; end if;
  if new.job_number is distinct from old.job_number or new.quotation_id is distinct from old.quotation_id then
    raise exception 'The job card number and quotation link cannot be changed.';
  end if;
  if new.admin_officer_id is distinct from old.admin_officer_id and not is_admin() then
    raise exception 'Only the CEO can appoint the administrative officer.';
  end if;
  return new;
end;$$;

-- p_project: an existing project without a job card, or null to create the project from p_details.
-- p_details (all optional except customer_name for a new project):
--   customer_name, customer_mobile, site_address, capacity_kwp, project_type, region, subsidy_job,
--   order_value, received, start_date (order date), target_commissioning, current_stage (stage_code),
--   admin_officer_id, legacy_ref, notes
create or replace function create_job_card_for_ongoing(p_project uuid, p_details jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  d        jsonb := coalesce(p_details, '{}'::jsonb);
  pr       projects%rowtype;
  v_job    text;
  v_start  date;
  v_sub    boolean;
  v_value  numeric;
  v_recv   numeric := greatest(coalesce(nullif(d->>'received', '')::numeric, 0), 0);
  v_cur    int;
  v_type   text;
  v_officer uuid := nullif(d->>'admin_officer_id', '')::uuid;
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager can create a job card.'; end if;
  if v_officer is not null and not is_admin() then v_officer := null; end if;   -- only the CEO appoints officers
  v_type := case when d->>'project_type' in ('residential','commercial','industrial','street_light','solar_pump','hybrid') then d->>'project_type' end;

  if p_project is null then
    if coalesce(trim(d->>'customer_name'), '') = '' then raise exception 'Enter the customer name.'; end if;
    insert into projects (name, customer_name, customer_mobile, site_address, project_type, capacity_kwp, region,
                          subsidy_job, order_value, start_date, target_commissioning, status, notes, created_by)
    values (trim(d->>'customer_name') || coalesce(' - ' || nullif(d->>'capacity_kwp', '') || ' kW', ''),
            trim(d->>'customer_name'), nullif(trim(d->>'customer_mobile'), ''), nullif(trim(d->>'site_address'), ''),
            coalesce(v_type, 'residential'), nullif(d->>'capacity_kwp', '')::numeric,
            case when d->>'region' in ('puducherry','tamilnadu') then d->>'region' end,
            coalesce((d->>'subsidy_job')::boolean, false), nullif(d->>'order_value', '')::numeric,
            coalesce(nullif(d->>'start_date', '')::date, (now() at time zone 'Asia/Kolkata')::date),
            nullif(d->>'target_commissioning', '')::date, 'in_progress', nullif(trim(d->>'notes'), ''), auth.uid())
    returning * into pr;
  else
    select * into pr from projects where id = p_project for update;
    if not found then raise exception 'Project not found.'; end if;
    if pr.job_number is not null then raise exception 'This project already has job card %.', pr.job_number; end if;
    -- Fill in what the old record lacks
    update projects set
      customer_mobile      = coalesce(nullif(trim(d->>'customer_mobile'), ''), customer_mobile),
      site_address         = coalesce(nullif(trim(d->>'site_address'), ''), site_address),
      capacity_kwp         = coalesce(nullif(d->>'capacity_kwp', '')::numeric, capacity_kwp),
      project_type         = coalesce(v_type, project_type),
      region               = coalesce(case when d->>'region' in ('puducherry','tamilnadu') then d->>'region' end, region),
      subsidy_job          = coalesce((d->>'subsidy_job')::boolean, subsidy_job),
      order_value          = coalesce(nullif(d->>'order_value', '')::numeric, order_value),
      start_date           = coalesce(nullif(d->>'start_date', '')::date, start_date),
      target_commissioning = coalesce(nullif(d->>'target_commissioning', '')::date, target_commissioning)
    where id = pr.id returning * into pr;
  end if;

  v_start := coalesce(pr.start_date, (now() at time zone 'Asia/Kolkata')::date);
  v_sub   := pr.subsidy_job;
  v_value := coalesce(pr.order_value, 0);
  if v_recv > v_value and v_value > 0 then raise exception 'Amount received (%) is more than the order value (%).', v_recv, v_value; end if;

  v_job := next_doc_number('JC');
  perform set_config('greenergy.converting', 'on', true);
  update projects set job_number = v_job, onboarded_at = now(),
         legacy_ref = coalesce(nullif(trim(d->>'legacy_ref'), ''), legacy_ref),
         admin_officer_id = coalesce(v_officer, admin_officer_id),
         status = case when status = 'planning' and coalesce(d->>'current_stage', 'order_confirmed') <> 'order_confirmed' then 'in_progress' else status end
   where id = pr.id;
  perform set_config('greenergy.converting', 'off', true);

  -- Milestones: everything before the current stage is done, the current one is in progress
  if not exists (select 1 from project_stage_history where project_id = pr.id) then
    select t.sort_order into v_cur from project_stage_template() t where t.stage_code = coalesce(nullif(d->>'current_stage', ''), 'order_confirmed');
    v_cur := coalesce(v_cur, 1);
    insert into project_stage_history (project_id, stage_code, stage_name, phase, sort_order, is_subsidy, status, planned_date, notes)
    select pr.id, t.stage_code, t.stage_name, t.phase, t.sort_order, t.is_subsidy,
           case when t.is_subsidy and not v_sub then 'skipped'
                when t.sort_order < v_cur then 'completed'
                when t.sort_order = v_cur then 'in_progress'
                else 'pending' end,
           case when t.day_offset is null or (t.is_subsidy and not v_sub) then null else v_start + t.day_offset end,
           case when t.sort_order < v_cur and not (t.is_subsidy and not v_sub) then 'Done before the CRM job card' end
      from project_stage_template() t;
  end if;

  -- Payments as an opening balance
  if v_value > 0 and not exists (select 1 from project_payments where project_id = pr.id) then
    if v_recv > 0 then
      insert into project_payments (project_id, milestone_name, amount, status, paid_date, notes, created_by)
      values (pr.id, 'Received before the CRM job card', v_recv, 'paid', (now() at time zone 'Asia/Kolkata')::date, 'Opening balance', auth.uid());
    end if;
    if v_value - v_recv > 0 then
      insert into project_payments (project_id, milestone_name, amount, status, notes, created_by)
      values (pr.id, 'Balance due', v_value - v_recv, 'pending', 'Opening balance', auth.uid());
    end if;
  end if;

  insert into audit_log (action_by, action_type, target_entity, target_id, description)
  values (auth.uid(), 'job_card_ongoing', 'projects', pr.id,
          'Job card ' || v_job || ' created for ongoing project ' || coalesce(pr.customer_name, pr.name) || coalesce(' (old ref ' || nullif(trim(d->>'legacy_ref'), '') || ')', ''));
  if v_officer is not null and v_officer <> auth.uid() then
    insert into notifications (user_id, type, title, message, link)
    values (v_officer, 'project', 'You are the administrative officer for a job card', v_job || ' · ' || coalesce(pr.customer_name, pr.name), '/staff/projects/' || pr.id);
  end if;

  return jsonb_build_object('project_id', pr.id, 'job_number', v_job);
end;$$;
revoke all on function create_job_card_for_ongoing(uuid, jsonb) from public, anon;
grant execute on function create_job_card_for_ongoing(uuid, jsonb) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ project_delete_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Project delete v1 (26 Nov 2026)
--  * The CEO can delete a project that has NO numbered job card (wrong, test or duplicate entries).
--  * A project with a job card (GSS/JC/...) or linked to a quotation can never be deleted, by anyone.
--  * Team assignments, field job cards (and their logs, materials, expenses), milestones, payments and
--    documents of the project go with it; tasks and attendance are kept (their project link is cleared).
--  * A reason is required; a snapshot of the project and what was removed is kept in the audit log.
-- Safe to run more than once.

create or replace function project_delete_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if old.job_number is not null then
    raise exception 'Project % has job card % and cannot be deleted.', old.project_number, old.job_number;
  end if;
  if old.quotation_id is not null or exists (select 1 from quotation_requests where project_id = old.id) then
    raise exception 'Project % is linked to a quotation and cannot be deleted.', old.project_number;
  end if;
  if coalesce(current_setting('greenergy.deleting_project', true), '') <> old.id::text then
    raise exception 'Use "Delete project" (CEO) to delete a project.';
  end if;
  return old;
end;$$;
drop trigger if exists trg_project_delete_guard on projects;
create trigger trg_project_delete_guard before delete on projects
  for each row execute function project_delete_guard();

-- What would be removed (shown to the CEO before deleting)
create or replace function project_delete_preview(p_project uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare pr projects%rowtype;
begin
  if not is_admin() then raise exception 'Only the CEO can delete a project.'; end if;
  select * into pr from projects where id = p_project;
  if not found then raise exception 'Project not found.'; end if;
  return jsonb_build_object(
    'can_delete',  pr.job_number is null and pr.quotation_id is null and not exists (select 1 from quotation_requests where project_id = pr.id),
    'job_number',  pr.job_number,
    'team',        (select count(*) from project_employees where project_id = pr.id),
    'field_job_cards', (select count(*) from job_cards where project_id = pr.id),
    'field_entries', (select count(*) from job_card_materials m join job_cards j on j.id = m.job_card_id where j.project_id = pr.id)
                   + (select count(*) from job_card_logs l join job_cards j on j.id = l.job_card_id where j.project_id = pr.id),
    'milestones',  (select count(*) from project_stage_history where project_id = pr.id),
    'payments_paid', (select count(*) from project_payments where project_id = pr.id and status = 'paid'),
    'documents',   (select count(*) from project_documents where project_id = pr.id),
    'tasks',       (select count(*) from tasks where project_id = pr.id),
    'attendance_days', (select count(*) from attendance where project_id = pr.id));
end;$$;

create or replace function delete_project(p_project uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare pr projects%rowtype; v_info jsonb;
begin
  if not is_admin() then raise exception 'Only the CEO can delete a project.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Give a short reason for deleting.'; end if;
  select * into pr from projects where id = p_project for update;
  if not found then raise exception 'Project not found.'; end if;
  v_info := project_delete_preview(p_project);
  if not (v_info->>'can_delete')::boolean then
    raise exception 'Project % has a job card or a quotation and cannot be deleted.', pr.project_number;
  end if;

  insert into audit_log (action_by, action_type, target_entity, target_id, description, metadata)
  values (auth.uid(), 'project_deleted', 'projects', pr.id,
          'Project ' || pr.project_number || ' (' || coalesce(pr.customer_name, pr.name) || ') deleted: ' || trim(p_reason),
          jsonb_build_object('project', to_jsonb(pr), 'removed', v_info, 'reason', trim(p_reason),
                             'team', (select coalesce(jsonb_agg(to_jsonb(e)), '[]') from project_employees e where e.project_id = pr.id),
                             'field_job_cards', (select coalesce(jsonb_agg(to_jsonb(j)), '[]') from job_cards j where j.project_id = pr.id)));

  perform set_config('greenergy.deleting_project', pr.id::text, true);
  delete from projects where id = pr.id;
  perform set_config('greenergy.deleting_project', '', true);
end;$$;

revoke all on function project_delete_preview(uuid), delete_project(uuid, text) from public, anon;
grant execute on function project_delete_preview(uuid), delete_project(uuid, text) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ task_delete_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Task delete v1 (26 Nov 2026)
--  * The CEO can delete any task (wrong, duplicate or no longer needed). Nobody else can.
--  * A copy of the deleted task is kept in the audit log.
--  * If the task was still open and assigned to someone else, that person is told it was removed.
-- Nothing else in the database refers to tasks, so deleting one cannot break other records.
-- Safe to run more than once.

drop policy if exists "CEO delete tasks" on tasks;
create policy "CEO delete tasks" on tasks for delete using (is_admin());

create or replace function task_after_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into audit_log (action_by, action_type, target_entity, target_id, description, metadata)
  values (auth.uid(), 'task_deleted', 'tasks', old.id,
          'Task "' || left(old.title, 120) || '" deleted by ' || coalesce(my_name(), 'the server'),
          jsonb_build_object('task', to_jsonb(old)));
  if old.assigned_to is not null and old.assigned_to is distinct from auth.uid()
     and old.status not in ('completed', 'cancelled') then
    insert into notifications (user_id, type, title, message, link)
    values (old.assigned_to, 'task', 'A task given to you was removed',
            '"' || left(old.title, 120) || '" was deleted by ' || coalesce(my_name(), 'the CEO') || '. You do not need to do it.', '/staff/tasks');
  end if;
  return old;
end;$$;
drop trigger if exists trg_task_after_delete on tasks;
create trigger trg_task_after_delete after delete on tasks
  for each row execute function task_after_delete();


-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_multi_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance: several clock-ins a day for site / O&M staff (27 Nov 2026)
--  * Each person has an attendance type, set by the CEO on the Attendance page:
--      office : one clock-in and one clock-out a day (office staff)
--      field  : clock in and out several times a day, e.g. one session per site visit
--               (installation, operation & maintenance)
--  * Every clock-in starts a new session (session 1, 2, 3 … of that day). A new session
--    can only start after the previous one is clocked out.
--  * Hours are per session; overtime is worked out on the DAY's total (over 8 h), shared
--    across the sessions so that adding them up gives the right figure.
--  * A session left open for more than 18 hours (forgot to clock out) no longer blocks
--    anything: the CEO corrects it, and the person can clock in again.
-- Needs attendance_v1.sql and attendance_devices_v1.sql first. Safe to run more than once.

-- ── Attendance type per person ──
do $$
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'profiles' and column_name = 'attendance_mode') then
    alter table profiles add column attendance_mode text not null default 'office';
    -- First run only: installation / O&M people start as "field"; the CEO can change anyone later
    update profiles set attendance_mode = 'field'
      where role <> 'admin'
        and (coalesce(department, '') ~* '(install|commission|o ?& ?m|operation|maintenance|service|site)'
          or coalesce(designation, '') ~* '(technician|electrician|helper|fitter|installer|o ?& ?m|maintenance|site engineer|field)');
  end if;
end $$;
alter table profiles drop constraint if exists profiles_attendance_mode_check;
alter table profiles add constraint profiles_attendance_mode_check check (attendance_mode in ('office', 'field'));

-- Only the CEO changes a person's attendance type (staff may still edit their own contact details)
create or replace function profile_attendance_mode_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.attendance_mode is distinct from old.attendance_mode then
    if auth.uid() is not null and not is_admin() then
      raise exception 'Only the CEO can change the attendance type.';
    end if;
    insert into audit_log (action_by, action_type, target_entity, target_id, description)
      values (auth.uid(), 'attendance_mode_changed', 'profiles', new.id,
              coalesce(new.full_name, 'Staff') || ': attendance type ' || old.attendance_mode || ' → ' || new.attendance_mode);
  end if;
  return new;
end;$$;
drop trigger if exists trg_profile_attendance_mode_guard on profiles;
create trigger trg_profile_attendance_mode_guard before update of attendance_mode on profiles
  for each row execute function profile_attendance_mode_guard();

-- ── Sessions ──
alter table attendance add column if not exists session_no integer not null default 1;
drop index if exists attendance_one_per_day;
create unique index if not exists attendance_session_per_day on attendance (employee_id, date, session_no);
create index if not exists attendance_open_sessions on attendance (employee_id) where clock_out_time is null;

create or replace function attendance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  ceo     boolean := auth.uid() is null or is_admin();   -- CEO or the server may correct records
  office  office_locations%rowtype;
  dist    double precision;
  slack   double precision;
  others  numeric;
begin
  if tg_op = 'INSERT' then
    if not ceo then
      new.date           := (now() at time zone 'Asia/Kolkata')::date;
      new.clock_in_time  := now();
      new.clock_out_time := null; new.clock_out_lat := null; new.clock_out_lng := null;
      new.total_hours    := null; new.overtime_hours := 0;
      new.attendance_status := 'present';
      new.is_location_mismatch := false;
    end if;
    new.session_no := coalesce((select max(session_no) from attendance
                                where employee_id = new.employee_id and date = new.date), 0) + 1;

    if new.work_type = 'office' then
      new.project_id := null;
      if new.clock_in_lat is null or new.clock_in_lng is null then
        raise exception 'Your location is needed to clock in at the office.';
      end if;
      select * into office from office_locations where active
        order by geo_distance_m(lat, lng, new.clock_in_lat::float8, new.clock_in_lng::float8) limit 1;
      if not found then
        raise exception 'The office location has not been set yet. Ask the CEO to set it in Attendance → Office location.';
      end if;
      dist := geo_distance_m(office.lat, office.lng, new.clock_in_lat::float8, new.clock_in_lng::float8);
      new.office_location_id  := office.id;
      new.clock_in_distance_m := round(dist::numeric);
      -- Indoor GPS is rough: allow the reported accuracy on top of the radius, up to 100 m
      slack := least(coalesce(new.clock_in_accuracy_m::float8, 0), 100);
      if dist > office.radius_m + slack and not ceo then
        raise exception 'You are about % m from %. Office clock-in works within % m. Go to the office (or near a window / outside for a better GPS signal) and try again.',
          round(dist::numeric), office.name, office.radius_m;
      end if;
    elsif new.project_id is null and not ceo then
      raise exception 'Choose the project / site you are working at.';
    end if;
    return new;
  end if;

  -- UPDATE
  if not ceo then
    if old.clock_out_time is not null then
      raise exception 'This session is already clocked out.';
    end if;
    -- Staff may only add their clock-out; everything about the clock-in stays as recorded
    new.employee_id := old.employee_id; new.date := old.date; new.session_no := old.session_no; new.work_type := old.work_type;
    new.project_id := old.project_id; new.office_location_id := old.office_location_id;
    new.clock_in_time := old.clock_in_time; new.clock_in_lat := old.clock_in_lat; new.clock_in_lng := old.clock_in_lng;
    new.clock_in_address := old.clock_in_address; new.clock_in_accuracy_m := old.clock_in_accuracy_m;
    new.clock_in_distance_m := old.clock_in_distance_m; new.attendance_status := old.attendance_status;
    if new.clock_out_time is not null then new.clock_out_time := now(); end if;
  end if;

  if new.clock_out_time is not null and new.work_type = 'office' and new.clock_out_lat is not null and new.clock_out_lng is not null then
    select * into office from office_locations where id = new.office_location_id;
    if found then
      dist := geo_distance_m(office.lat, office.lng, new.clock_out_lat::float8, new.clock_out_lng::float8);
      new.clock_out_distance_m := round(dist::numeric);
      -- Clock-out is never blocked; leaving from somewhere else is flagged for the CEO
      new.is_location_mismatch := dist > office.radius_m + least(coalesce(new.clock_out_accuracy_m::float8, 0), 100);
    end if;
  end if;

  if new.clock_out_time is not null and new.clock_in_time is not null then
    new.total_hours := round((extract(epoch from new.clock_out_time - new.clock_in_time) / 3600)::numeric, 2);
    -- Overtime counts on the day's total: this session gets the part that goes past 8 h
    select coalesce(sum(total_hours), 0) into others from attendance
      where employee_id = new.employee_id and date = new.date and id <> new.id and total_hours is not null;
    new.overtime_hours := greatest(0, others + new.total_hours - 8) - greatest(0, others - 8);
  else
    new.total_hours := null; new.overtime_hours := 0;
  end if;
  return new;
end;$$;

drop trigger if exists trg_attendance_guard on attendance;
create trigger trg_attendance_guard before insert or update on attendance
  for each row execute function attendance_guard();

-- ── Clock in / out ──
create or replace function attendance_clock_in(
  p_device uuid, p_secret text, p_work_type text, p_project uuid,
  p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare dev uuid; new_id uuid; mode text; open_rec attendance%rowtype; today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if is_admin() then raise exception 'The CEO does not clock in or out.'; end if;
  dev := _check_attendance_device(p_device, p_secret);
  perform pg_advisory_xact_lock(hashtext('attendance:' || auth.uid()::text));   -- a double tap cannot start two sessions

  select coalesce(attendance_mode, 'office') into mode from profiles where id = auth.uid();
  select * into open_rec from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time > now() - interval '18 hours'
    order by clock_in_time desc limit 1;
  if found then
    raise exception 'You are still clocked in since % (session %). Clock out first.',
      to_char(open_rec.clock_in_time at time zone 'Asia/Kolkata', 'HH12:MI AM'), open_rec.session_no;
  end if;
  if mode = 'office' and exists (select 1 from attendance where employee_id = auth.uid() and date = today) then
    raise exception 'You have already clocked in today. (Office attendance is once a day; ask the CEO if you need several sessions for site work.)';
  end if;
  if (select count(*) from attendance where employee_id = auth.uid() and date = today) >= 12 then
    raise exception 'That is 12 sessions today already. Ask the CEO to correct your attendance.';
  end if;
  if p_work_type = 'site' and p_project is not null and not is_manager() and not exists (
    select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null) then
    raise exception 'You are not assigned to that project.';
  end if;
  -- attendance_guard sets the time, date and session number and checks the office distance
  insert into attendance (employee_id, work_type, project_id, clock_in_lat, clock_in_lng, clock_in_accuracy_m, clock_in_address, device_id)
    values (auth.uid(), case when p_work_type = 'office' then 'office' else 'site' end, p_project,
            p_lat, p_lng, p_accuracy, left(p_address, 500), dev)
    returning id into new_id;
  return new_id;
end;$$;

create or replace function attendance_clock_out(
  p_device uuid, p_secret text, p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare rec attendance%rowtype;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  perform _check_attendance_device(p_device, p_secret);
  perform pg_advisory_xact_lock(hashtext('attendance:' || auth.uid()::text));
  select * into rec from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time is not null
    order by clock_in_time desc limit 1;
  if not found then raise exception 'You are not clocked in.'; end if;
  if rec.clock_in_time < now() - interval '18 hours' then
    raise exception 'You did not clock out on % (clocked in at %). Ask the CEO to correct that day. You can clock in again now.',
      to_char(rec.date, 'DD Mon'), to_char(rec.clock_in_time at time zone 'Asia/Kolkata', 'HH12:MI AM');
  end if;
  update attendance set clock_out_time = now(), clock_out_lat = p_lat, clock_out_lng = p_lng,
         clock_out_accuracy_m = p_accuracy, clock_out_address = left(p_address, 500)
    where id = rec.id;
  return rec.id;
end;$$;

revoke all on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) from public, anon;
grant execute on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ growth_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Growth v1 (27 Nov 2026): selling and cash, not more control.
--  1. Control room data: what is stuck today (the screens read the tables directly).
--  2. Why deals are lost: a reason code on every lost quotation (Pareto chart on Sales insights).
--  3. Speed to lead: when a lead was first contacted; an alert when nobody has called within the hour.
--  4. Auto-approval: quotations inside the CEO's own rules (size, margin, discount) are approved
--     without waiting for the CEO. The CEO switches it on in Business rules; it starts OFF.
--  6. Money: due dates follow the milestones, part payments, receipts, overdue alerts.
--  7. Referrals and neighbour group offers: a referral code for every customer, group links,
--     rewards due when a referred customer becomes a job.
--  9. Commissioning checklist with photos and the customer's signature; the "Commissioning"
--     milestone cannot be ticked until it is complete. A customer report link (no login).
-- Needs everything before it in UPGRADE_EXISTING_PROJECT.sql. Safe to run more than once.

-- ═══ Business rules (set by the CEO) ════════════════════════════════════════
create table if not exists business_settings (
  key        text primary key,
  data       jsonb not null default '{}',
  updated_by uuid references profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);
alter table business_settings enable row level security;
drop policy if exists "staff_read_settings" on business_settings;
create policy "staff_read_settings" on business_settings for select using (is_staff());
drop policy if exists "ceo_write_settings" on business_settings;
create policy "ceo_write_settings" on business_settings for all using (is_admin()) with check (is_admin());

insert into business_settings (key, data) values
  ('auto_approval', '{"enabled": false, "max_kw": 10, "min_margin_pct": 15, "max_discount_pct": 3, "domestic_only": true}'),
  ('referral',      '{"reward_amount": 2000, "reward_note": "Paid to the referring customer after the new customer''s system is commissioned."}'),
  ('group_buy',     '{"tiers": [{"homes": 3, "discount_pct": 3}, {"homes": 5, "discount_pct": 5}]}'),
  ('alerts',        '{"first_call_minutes": 60, "day_start": 9, "day_end": 19}'),
  ('company',       '{"name": "Greenergy Solar Solutions", "address": "Lawspet, Puducherry", "state": "Puducherry", "phone": "+91 99432 56109", "email": "", "gstin": "", "website": "https://www.greenergypdy.com", "upi_id": "", "bank": ""}')
on conflict (key) do nothing;

create or replace function setting(p_key text) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce((select data from business_settings where key = p_key), '{}'::jsonb);
$$;

-- ═══ Quotation: lost reason, first contact, lead details, referral / group ═══
alter table quotation_requests add column if not exists lost_reason_code      text;
alter table quotation_requests add column if not exists first_contact_at      timestamptz;
alter table quotation_requests add column if not exists first_call_alerted_at timestamptz;
alter table quotation_requests add column if not exists follow_up_alerted_on  date;
alter table quotation_requests add column if not exists monthly_bill_range    text;
alter table quotation_requests add column if not exists pincode               text;
alter table quotation_requests add column if not exists referred_by_project   uuid references projects(id) on delete set null;
alter table quotation_requests add column if not exists group_buy_id          uuid;
alter table quotation_requests add column if not exists auto_approved         boolean not null default false;
alter table quotation_requests drop constraint if exists qr_lost_reason_chk;
alter table quotation_requests add constraint qr_lost_reason_chk check (lost_reason_code in (
  'price_high', 'competitor', 'subsidy_doubt', 'finance', 'site_unsuitable', 'no_response', 'postponed', 'other'));

-- Existing leads that already moved on were contacted (no false "not called" alerts)
update quotation_requests set first_contact_at = coalesce(site_visit_at, sent_to_customer_at, updated_at, created_at)
 where first_contact_at is null and status <> 'new';

-- The allocation rules list exactly which columns each assignee may change: add the automatic ones
create or replace function quotation_role_guard()
returns trigger language plpgsql set search_path = public as $$
declare
  uid     uuid := auth.uid();
  visitor boolean;
  fu      boolean;
  allowed text[] := array['updated_at', 'next_follow_up_date', 'follow_up_count', 'lead_temperature', 'lead_temperature_note', 'lead_temperature_at',
                          'first_contact_at', 'first_call_alerted_at', 'follow_up_alerted_on'];
  move    text := old.status || '>' || new.status;
begin
  if uid is null or is_manager() or can_manage_quotations() or old.assigned_sales_id = uid
     or coalesce(current_setting('greenergy.converting', true), '') = 'on' then
    return new;
  end if;
  visitor := old.assigned_engineer_id = uid;
  fu      := old.follow_up_manager_id = uid;
  if visitor then
    allowed := allowed || array['status', 'site_visit_at', 'site_visit_done_at', 'site_visit_notes', 'site_visit_lat', 'site_visit_lng',
      'address', 'city', 'eb_consumer_number', 'sanctioned_load_kw', 'avg_monthly_units', 'avg_monthly_bill', 'roof_type',
      'available_roof_area_sqft', 'current_phase', 'notes', 'roof_photo_url', 'eb_bill_url', 'pincode'];
  end if;
  if fu then
    allowed := allowed || array['status', 'sent_to_customer_at', 'accepted_by_name', 'accepted_via', 'accepted_note',
      'customer_response_at', 'lost_reason', 'lost_reason_code'];
  end if;
  if (to_jsonb(new) - allowed) is distinct from (to_jsonb(old) - allowed) then
    raise exception '%', case
      when visitor and fu then 'You can update the site visit and the follow-up of this quotation. Prices are changed by the person preparing it.'
      when visitor then 'You can update the site visit of this quotation. The quotation itself is prepared by someone else.'
      when fu then 'You can follow up this quotation. Changes to it are made by the person preparing it.'
      else 'You do not have access to change this quotation.' end;
  end if;
  if new.status is distinct from old.status and not (
       (visitor and old.status in ('new', 'sales_review', 'site_details_pending', 'site_visit_scheduled')
                and new.status in ('site_visit_scheduled', 'site_visit_done'))
    or (fu and move in ('approved>sent_to_customer', 'sent_to_customer>customer_accepted', 'customer_accepted>advance_pending',
                        'sent_to_customer>cancelled', 'customer_accepted>cancelled', 'advance_pending>cancelled'))) then
    raise exception 'This step is done by the person preparing the quotation, the admin manager or the CEO.';
  end if;
  return new;
end;$$;

-- First contact: a lead typed in by staff (phone call, walk-in) is contacted already; a website lead
-- is contacted at the first logged call / WhatsApp / visit, or when a site visit is planned.
create or replace function quotation_first_contact()
returns trigger language plpgsql set search_path = public as $$
begin
  if auth.uid() is null or new.first_contact_at is not null then return new; end if;
  if tg_op = 'INSERT'
     or new.site_visit_at is not null or new.site_visit_done_at is not null
     or new.status not in ('new', 'sales_review', 'site_details_pending') then
    new.first_contact_at := now();
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_first_contact on quotation_requests;
create trigger trg_quotation_first_contact before insert or update on quotation_requests
  for each row execute function quotation_first_contact();

create or replace function follow_up_first_contact()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update quotation_requests set first_contact_at = new.created_at
   where id = new.quotation_id and first_contact_at is null and status <> 'project_created';
  return new;
end;$$;
drop trigger if exists trg_follow_up_first_contact on quotation_follow_ups;
create trigger trg_follow_up_first_contact after insert on quotation_follow_ups
  for each row execute function follow_up_first_contact();

-- ═══ 4. Auto-approval check ═════════════════════════════════════════════════
-- Returns whether a quotation is inside the CEO's rules. Margin = (price before GST − cost) / price.
-- Only list-priced quotations without extra items qualify (extras have no cost in the price list).
create or replace function quotation_auto_approval(p_quotation uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  q        quotation_requests%rowtype;
  r        jsonb := setting('auto_approval');
  c        quotation_costings%rowtype;
  why      text[] := '{}';
  cost     numeric;
  sold     numeric;
  margin   numeric;
  disc     numeric;
  cost_kw  numeric;
  priv     boolean := auth.uid() is null or is_manager();
begin
  if auth.uid() is not null and not can_view_quotation(p_quotation) then raise exception 'Quotation not found.'; end if;
  select * into q from quotation_requests where id = p_quotation;
  if not found then raise exception 'Quotation not found.'; end if;
  if not coalesce((r->>'enabled')::boolean, false) then
    return jsonb_build_object('eligible', false, 'enabled', false, 'reasons', jsonb_build_array('Auto-approval is switched off'));
  end if;
  select * into c from quotation_costings where quotation_id = q.id;
  sold := coalesce(q.admin_system_cost, 0);
  cost := (c.data->>'subtotal')::numeric;
  select sum(l.qty) / 1000 into cost_kw from jsonb_to_recordset(coalesce(c.data->'lines', '[]')) as l(id text, qty numeric) where l.id = 'panels';

  if not q.priced_from_list or c.quotation_id is null or cost is null then why := why || 'Not priced from the price list (use "Re-price")'::text; end if;
  if c.quotation_id is not null and cost_kw is not null and abs(cost_kw - coalesce(q.admin_capacity_kw, 0)) > 0.05 then
    why := why || 'Size changed after pricing (press "Re-price")'::text;
  end if;
  if exists (select 1 from quotation_line_items where quotation_id = q.id and coalesce(is_included, true)) then why := why || 'Has extra items'::text; end if;
  if coalesce(q.admin_capacity_kw, 0) <= 0 or q.admin_capacity_kw > coalesce((r->>'max_kw')::numeric, 0) then
    why := why || format('Size %s kW is above %s kW', coalesce(q.admin_capacity_kw::text, '?'), r->>'max_kw');
  end if;
  if coalesce((r->>'domestic_only')::boolean, true) and coalesce(q.consumer_type, 'domestic') <> 'domestic' then why := why || 'Not a home (domestic) system'::text; end if;
  if sold <= 0 then why := why || 'No price yet'::text; end if;
  disc := case when sold + coalesce(q.discount, 0) > 0 then round(coalesce(q.discount, 0) * 100 / (sold + coalesce(q.discount, 0)), 1) else 0 end;
  if disc > coalesce((r->>'max_discount_pct')::numeric, 0) then
    why := why || case when priv then format('Discount %s%% is above %s%%', disc, r->>'max_discount_pct') else 'Discount is above the limit' end;
  end if;
  if cost is not null and sold > 0 then
    margin := round((sold - cost) * 100 / sold, 1);
    if margin < coalesce((r->>'min_margin_pct')::numeric, 100) then
      why := why || case when priv then format('Margin %s%% is below %s%%', margin, r->>'min_margin_pct') else 'Margin is below the limit' end;
    end if;
  end if;
  return jsonb_build_object('eligible', cardinality(why) = 0, 'enabled', true, 'reasons', to_jsonb(why))
         || case when priv then jsonb_build_object('margin_pct', margin, 'discount_pct', disc) else '{}'::jsonb end;
end;$$;
revoke all on function quotation_auto_approval(uuid) from public, anon;
grant execute on function quotation_auto_approval(uuid) to authenticated;

-- ═══ 7. Referrals and neighbour groups ══════════════════════════════════════
alter table projects add column if not exists referral_code text;
alter table projects add column if not exists report_token  uuid default gen_random_uuid();
do $$ begin
  alter table projects add constraint projects_referral_code_key unique (referral_code);
exception when duplicate_object or duplicate_table then null; end $$;
do $$ begin
  alter table projects add constraint projects_report_token_key unique (report_token);
exception when duplicate_object or duplicate_table then null; end $$;
update projects set report_token = gen_random_uuid() where report_token is null;

-- Short code without look-alike letters, e.g. GK7M4Q
create or replace function new_short_code(p_prefix text) returns text language plpgsql volatile as $$
declare a text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; s text := p_prefix; i int;
begin
  for i in 1..5 loop s := s || substr(a, 1 + floor(random() * length(a))::int, 1); end loop;
  return s;
end;$$;

create or replace function project_referral_code()
returns trigger language plpgsql set search_path = public as $$
declare tries int := 0;
begin
  if new.referral_code is null then
    loop
      new.referral_code := new_short_code('G');
      exit when not exists (select 1 from projects where referral_code = new.referral_code) or tries > 20;
      tries := tries + 1;
    end loop;
  end if;
  new.report_token := coalesce(new.report_token, gen_random_uuid());
  return new;
end;$$;
drop trigger if exists trg_project_referral_code on projects;
create trigger trg_project_referral_code before insert on projects
  for each row execute function project_referral_code();
do $$ declare p record; begin
  for p in select id from projects where referral_code is null loop
    update projects set referral_code = (select c from (select new_short_code('G') c) x where not exists (select 1 from projects where referral_code = x.c)) where id = p.id;
  end loop;
end $$;

create table if not exists group_buys (
  id         uuid default gen_random_uuid() primary key,
  code       text not null unique,
  name       text not null check (char_length(name) between 2 and 120),
  area       text,
  status     text not null default 'open' check (status in ('open', 'closed')),
  closes_on  date,
  notes      text,
  created_by uuid references profiles(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);
alter table group_buys enable row level security;
drop policy if exists "staff_read_groups" on group_buys;
create policy "staff_read_groups" on group_buys for select using (is_staff());
drop policy if exists "managers_write_groups" on group_buys;
create policy "managers_write_groups" on group_buys for all using (is_manager()) with check (is_manager());
create or replace function group_buy_code()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.code is null or new.code = '' then
    loop
      new.code := new_short_code('N');
      exit when not exists (select 1 from group_buys where code = new.code);
    end loop;
  end if;
  new.code := upper(new.code);
  return new;
end;$$;
drop trigger if exists trg_group_buy_code on group_buys;
create trigger trg_group_buy_code before insert on group_buys for each row execute function group_buy_code();
do $$ begin
  alter table quotation_requests add constraint qr_group_buy_fk foreign key (group_buy_id) references group_buys(id) on delete set null;
exception when duplicate_object then null; end $$;

create table if not exists referral_rewards (
  id                  uuid default gen_random_uuid() primary key,
  quotation_id        uuid not null unique references quotation_requests(id) on delete cascade,
  referrer_project_id uuid references projects(id) on delete set null,
  amount              numeric not null default 0,
  status              text not null default 'due' check (status in ('due', 'paid', 'cancelled')),
  paid_at             timestamptz,
  paid_by             uuid references profiles(id) on delete set null,
  note                text,
  created_at          timestamptz not null default now()
);
alter table referral_rewards enable row level security;
drop policy if exists "managers_rewards" on referral_rewards;
create policy "managers_rewards" on referral_rewards for select using (is_manager());
-- Changes only through mark_referral_reward()

-- A referred lead that becomes a job: reward due, managers told
create or replace function quotation_referral_reward()
returns trigger language plpgsql security definer set search_path = public as $$
declare ref projects%rowtype; amt numeric := coalesce((setting('referral')->>'reward_amount')::numeric, 0);
begin
  if new.status = 'project_created' and old.status <> 'project_created' and new.referred_by_project is not null then
    select * into ref from projects where id = new.referred_by_project;
    insert into referral_rewards (quotation_id, referrer_project_id, amount) values (new.id, new.referred_by_project, amt)
      on conflict (quotation_id) do nothing;
    insert into notifications (user_id, type, title, message, link)
      select id, 'referral', 'Referral reward due',
             coalesce(ref.customer_name, 'A customer') || ' referred ' || new.customer_name || ' (now job ' || coalesce(new.job_number, '') || '). Reward ₹' || amt,
             '/staff/growth'
        from profiles where role in ('admin', 'task_manager') and status = 'active';
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_referral_reward on quotation_requests;
create trigger trg_quotation_referral_reward after update on quotation_requests
  for each row execute function quotation_referral_reward();

create or replace function mark_referral_reward(p_reward uuid, p_status text, p_note text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager can do this.'; end if;
  if p_status not in ('paid', 'cancelled', 'due') then raise exception 'Unknown status.'; end if;
  update referral_rewards set status = p_status, note = left(p_note, 300),
         paid_at = case when p_status = 'paid' then now() end, paid_by = case when p_status = 'paid' then auth.uid() end
   where id = p_reward;
  if not found then raise exception 'Reward not found.'; end if;
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'referral_reward_' || p_status, 'referral_rewards', p_reward, coalesce(p_note, ''));
end;$$;
revoke all on function mark_referral_reward(uuid, text, text) from public, anon;
grant execute on function mark_referral_reward(uuid, text, text) to authenticated;

-- ═══ 6. Payments: due dates follow milestones, part payments, receipts ══════
alter table project_payments add column if not exists amount_received numeric not null default 0;
alter table project_payments add column if not exists trigger_stage   text;
alter table project_payments add column if not exists alerted_at      timestamptz;

create or replace function payment_stage_of(p_name text) returns text language sql immutable as $$
  select case
    when p_name ~* '^advance'                     then 'order_confirmed'
    when p_name ~* 'material'                     then 'material_procurement'
    when p_name ~* 'commission|handover|balance'  then 'commissioning'
    else null end;
$$;
update project_payments set trigger_stage = payment_stage_of(milestone_name) where trigger_stage is null and status <> 'paid';
update project_payments set amount_received = amount where status = 'paid' and amount_received = 0;

create or replace function payment_defaults()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.trigger_stage := coalesce(new.trigger_stage, payment_stage_of(new.milestone_name));
  if new.due_date is null and new.trigger_stage is not null then
    select coalesce(actual_date, planned_date) into new.due_date from project_stage_history
     where project_id = new.project_id and stage_code = new.trigger_stage;
  end if;
  if new.status = 'paid' and coalesce(new.amount_received, 0) = 0 then new.amount_received := new.amount; end if;
  return new;
end;$$;
drop trigger if exists trg_payment_defaults on project_payments;
create trigger trg_payment_defaults before insert on project_payments for each row execute function payment_defaults();
update project_payments p set due_date = coalesce(s.actual_date, s.planned_date)
  from project_stage_history s
 where p.due_date is null and p.status <> 'paid' and s.project_id = p.project_id and s.stage_code = p.trigger_stage;

-- A milestone's date moves → the payment tied to it moves too
create or replace function stage_payment_sync()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(new.actual_date, new.planned_date) is distinct from coalesce(old.actual_date, old.planned_date) then
    update project_payments set due_date = coalesce(new.actual_date, new.planned_date), alerted_at = null
     where project_id = new.project_id and trigger_stage = new.stage_code and status not in ('paid', 'waived');
  end if;
  return new;
end;$$;
drop trigger if exists trg_stage_payment_sync on project_stage_history;
create trigger trg_stage_payment_sync after update on project_stage_history
  for each row execute function stage_payment_sync();

create table if not exists payment_receipts (
  id          uuid default gen_random_uuid() primary key,
  payment_id  uuid not null references project_payments(id) on delete cascade,
  project_id  uuid not null references projects(id) on delete cascade,
  amount      numeric not null check (amount > 0),
  mode        text check (mode in ('cash', 'upi', 'neft', 'cheque', 'subsidy', 'other')),
  reference   text,
  received_on date not null,
  recorded_by uuid references profiles(id) on delete set null,
  recorded_by_name text,
  created_at  timestamptz not null default now()
);
alter table payment_receipts enable row level security;
drop policy if exists "view_receipts" on payment_receipts;
create policy "view_receipts" on payment_receipts for select using (can_view_project(project_id));

create or replace function record_payment(p_payment uuid, p_amount numeric, p_mode text, p_ref text, p_date date)
returns jsonb language plpgsql security definer set search_path = public as $$
declare pay project_payments%rowtype; got numeric; left_due numeric;
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager records payments.'; end if;
  select * into pay from project_payments where id = p_payment for update;
  if not found then raise exception 'Payment not found.'; end if;
  if pay.status in ('paid', 'waived') then raise exception 'This payment is already closed.'; end if;
  if coalesce(p_amount, 0) <= 0 then raise exception 'Enter the amount received.'; end if;
  if p_date is null or p_date > (now() at time zone 'Asia/Kolkata')::date then raise exception 'Choose the date the money was received (not in the future).'; end if;
  left_due := pay.amount - coalesce(pay.amount_received, 0);
  if p_amount > left_due + 1 then raise exception 'That is more than the ₹% still due on this payment.', round(left_due); end if;
  got := coalesce(pay.amount_received, 0) + p_amount;
  insert into payment_receipts (payment_id, project_id, amount, mode, reference, received_on, recorded_by, recorded_by_name)
    values (pay.id, pay.project_id, p_amount, nullif(p_mode, ''), nullif(left(p_ref, 120), ''), p_date, auth.uid(), my_name());
  update project_payments set amount_received = got,
         status = case when got >= amount - 1 then 'paid' else 'partial' end,
         paid_date = case when got >= amount - 1 then p_date else paid_date end,
         payment_mode = case when p_mode in ('cash', 'upi', 'neft', 'cheque', 'other') then p_mode else coalesce(payment_mode, 'other') end,
         reference_number = nullif(concat_ws(' · ', nullif(reference_number, ''), nullif(left(p_ref, 120), '')), '')
   where id = pay.id;
  -- Everything paid → the "Final payment received" milestone is done
  if not exists (select 1 from project_payments where project_id = pay.project_id and status not in ('paid', 'waived')) then
    update project_stage_history set status = 'completed', actual_date = coalesce(actual_date, p_date)
     where project_id = pay.project_id and stage_code = 'final_payment' and status not in ('completed', 'skipped');
  end if;
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'payment_recorded', 'project_payments', pay.id, '₹' || round(p_amount) || ' received for "' || pay.milestone_name || '"');
  return jsonb_build_object('received', got, 'due', greatest(pay.amount - got, 0));
end;$$;
revoke all on function record_payment(uuid, numeric, text, text, date) from public, anon;
grant execute on function record_payment(uuid, numeric, text, text, date) to authenticated;

-- ═══ 9. Commissioning checklist ═════════════════════════════════════════════
create table if not exists commissioning_reports (
  project_id      uuid primary key references projects(id) on delete cascade,
  data            jsonb not null default '{}',
  photos          jsonb not null default '{}',
  signature_url   text,
  signed_name     text,
  signed_at       timestamptz,
  completed_at    timestamptz,
  completed_by    uuid references profiles(id) on delete set null,
  override_reason text,
  updated_by      uuid references profiles(id) on delete set null,
  updated_by_name text,
  updated_at      timestamptz not null default now()
);
alter table commissioning_reports enable row level security;

create or replace function can_work_on_project(p_project uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select is_manager() or is_project_officer(p_project)
      or exists (select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null and is_staff());
$$;
drop policy if exists "view_commissioning" on commissioning_reports;
create policy "view_commissioning" on commissioning_reports for select using (can_view_project(project_id));
drop policy if exists "add_commissioning" on commissioning_reports;
create policy "add_commissioning" on commissioning_reports for insert with check (can_work_on_project(project_id));
drop policy if exists "edit_commissioning" on commissioning_reports;
create policy "edit_commissioning" on commissioning_reports for update using (can_work_on_project(project_id)) with check (can_work_on_project(project_id));

-- What is still missing (the same list the page shows)
create or replace function commissioning_missing(p_project uuid)
returns text[] language plpgsql stable security definer set search_path = public as $$
declare r commissioning_reports%rowtype; miss text[] := '{}'; k text;
  photo_keys text[] := array['array', 'structure', 'inverter', 'acdb_dcdb', 'earthing', 'meter'];
  photo_names text[] := array['Photo: panel array', 'Photo: mounting structure', 'Photo: inverter (switched on)', 'Photo: ACDB / DCDB',
                              'Photo: earthing & lightning arrester', 'Photo: net meter with reading'];
  data_keys text[] := array['inverter_serial', 'panel_serials', 'string_voc', 'insulation_mohm', 'earth_ohm', 'meter_reading',
                            'check_monitoring', 'check_training', 'check_warranty'];
  data_names text[] := array['Inverter serial number', 'Panel serial numbers', 'String voltage (Voc)', 'Insulation resistance',
                             'Earth resistance', 'Meter reading at commissioning', 'Monitoring app set up', 'Customer shown how to use and clean',
                             'Warranty cards handed over'];
  i int;
begin
  select * into r from commissioning_reports where project_id = p_project;
  if not found then return array['Checklist not started']; end if;
  if r.override_reason is not null then return '{}'; end if;
  for i in 1..array_length(photo_keys, 1) loop
    if jsonb_array_length(coalesce(r.photos->photo_keys[i], '[]')) = 0 then miss := miss || photo_names[i]; end if;
  end loop;
  for i in 1..array_length(data_keys, 1) loop
    k := data_keys[i];
    if k like 'check_%' then
      if not coalesce((r.data->>k)::boolean, false) then miss := miss || data_names[i]; end if;
    elsif coalesce(trim(r.data->>k), '') = '' then miss := miss || data_names[i];
    end if;
  end loop;
  if coalesce(trim(r.signed_name), '') = '' or r.signature_url is null then miss := miss || 'Customer signature'::text; end if;
  return miss;
end;$$;

create or replace function commissioning_touch()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and old.completed_at is not null and not is_manager() and auth.uid() is not null then
    raise exception 'The commissioning report is complete. Ask the admin manager or CEO to change it.';
  end if;
  if auth.uid() is not null and not is_admin() then
    new.override_reason := case when tg_op = 'UPDATE' then old.override_reason end;
  end if;
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  new.updated_by_name := coalesce(my_name(), new.updated_by_name);
  new.updated_at := now();
  if new.signature_url is not null and new.signed_at is null then new.signed_at := now(); end if;
  return new;
end;$$;
drop trigger if exists trg_commissioning_touch on commissioning_reports;
create trigger trg_commissioning_touch before insert or update on commissioning_reports
  for each row execute function commissioning_touch();

-- Complete the report (everything present), or the CEO completes it with a written reason
create or replace function complete_commissioning(p_project uuid, p_override_reason text default null)
returns text[] language plpgsql security definer set search_path = public as $$
declare miss text[];
begin
  if not can_work_on_project(p_project) then raise exception 'You are not on this project.'; end if;
  if nullif(trim(p_override_reason), '') is not null then
    if not is_admin() then raise exception 'Only the CEO can complete the report with items missing.'; end if;
    insert into commissioning_reports (project_id) values (p_project) on conflict (project_id) do nothing;
    update commissioning_reports set override_reason = left(trim(p_override_reason), 300) where project_id = p_project;
  end if;
  miss := commissioning_missing(p_project);
  if cardinality(miss) > 0 then return miss; end if;
  update commissioning_reports set completed_at = coalesce(completed_at, now()), completed_by = coalesce(completed_by, auth.uid())
   where project_id = p_project;
  update project_stage_history set status = 'completed'
   where project_id = p_project and stage_code = 'testing' and status not in ('completed', 'skipped');
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'commissioning_completed', 'projects', p_project,
            'Commissioning checklist completed' || coalesce(' (CEO override: ' || nullif(trim(p_override_reason), '') || ')', ''));
  return '{}';
end;$$;
revoke all on function complete_commissioning(uuid, text) from public, anon;
grant execute on function complete_commissioning(uuid, text) to authenticated;

-- Poka-yoke: "Commissioning certificate issued" cannot be ticked before the checklist is complete
-- (projects taken over as "ongoing" are exempt: their earlier work was not recorded here)
create or replace function stage_commissioning_gate()
returns trigger language plpgsql security definer set search_path = public as $$
declare miss text[];
begin
  if new.stage_code = 'commissioning' and new.status = 'completed' and old.status <> 'completed'
     and not exists (select 1 from projects where id = new.project_id and onboarded_at is not null)
     and not exists (select 1 from commissioning_reports where project_id = new.project_id and completed_at is not null) then
    miss := commissioning_missing(new.project_id);
    raise exception 'Complete the commissioning checklist first (missing: %).', array_to_string(miss[1:4], ', ') || case when cardinality(miss) > 4 then ' …' else '' end;
  end if;
  return new;
end;$$;
drop trigger if exists trg_stage_commissioning_gate on project_stage_history;
create trigger trg_stage_commissioning_gate before update on project_stage_history
  for each row execute function stage_commissioning_gate();

-- ═══ 3 & 6. Alerts (every 15 minutes with pg_cron; also whenever a manager opens the Control room) ═══
create table if not exists alert_runs (id int primary key default 1 check (id = 1), last_run timestamptz);
alter table alert_runs enable row level security;   -- no policies: only the function below

create or replace function notify_managers(p_type text, p_title text, p_message text, p_link text, p_also uuid[] default '{}')
returns void language sql security definer set search_path = public as $$
  insert into notifications (user_id, type, title, message, link)
  select distinct u, p_type, p_title, p_message, p_link
    from (select id as u from profiles where role in ('admin', 'task_manager') and status = 'active'
          union select unnest(p_also)) x
   where u is not null;
$$;
revoke all on function notify_managers(text, text, text, text, uuid[]) from public, anon, authenticated;

create or replace function run_scheduled_alerts()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  a        jsonb := setting('alerts');
  mins     int := coalesce((a->>'first_call_minutes')::int, 60);
  local_t  timestamp := now() at time zone 'Asia/Kolkata';
  today    date := (now() at time zone 'Asia/Kolkata')::date;
  in_hours boolean := extract(hour from local_t) >= coalesce((a->>'day_start')::int, 9) and extract(hour from local_t) < coalesce((a->>'day_end')::int, 19);
  q        record;
  n_lead   int := 0; n_fu int := 0; n_pay int := 0; n_svc jsonb := '{}';
  last     timestamptz;
begin
  if auth.uid() is not null and not is_staff() then raise exception 'Please sign in again.'; end if;
  if not pg_try_advisory_xact_lock(hashtext('greenergy-alerts')) then return '{"skipped": true}'; end if;
  select last_run into last from alert_runs where id = 1;
  if auth.uid() is not null and last > now() - interval '5 minutes' then return '{"skipped": true}'; end if;
  insert into alert_runs (id, last_run) values (1, now()) on conflict (id) do update set last_run = now();

  -- Leads nobody has called (working hours only, last 14 days)
  if in_hours then
    for q in select * from quotation_requests
              where first_contact_at is null and first_call_alerted_at is null
                and status in ('new', 'sales_review', 'site_details_pending')
                and created_at < now() - make_interval(mins => mins) and created_at > now() - interval '14 days' loop
      perform notify_managers('lead', 'Call this lead now — not contacted for ' ||
                case when now() - q.created_at > interval '2 hours' then round(extract(epoch from now() - q.created_at) / 3600) || ' hours' else mins || '+ minutes' end,
                q.customer_name || ' · ' || q.mobile || coalesce(' · ' || q.city, '') || ' · ' || coalesce(q.quotation_number, ''),
                '/staff/quotations/' || q.id, array[q.assigned_engineer_id, q.assigned_sales_id, q.follow_up_manager_id]);
      update quotation_requests set first_call_alerted_at = now() where id = q.id;
      n_lead := n_lead + 1;
    end loop;
  end if;

  -- Follow-ups due today or overdue: once a day, to the follow-up person (or the preparer)
  if extract(hour from local_t) >= 8 then
    for q in select * from quotation_requests
              where next_follow_up_date <= today and follow_up_alerted_on is distinct from today
                and status not in ('project_created', 'cancelled', 'rejected') loop
      insert into notifications (user_id, type, title, message, link)
        select u, 'quotation', case when q.next_follow_up_date < today then 'Follow-up overdue' else 'Follow-up due today' end,
               q.customer_name || ' · ' || q.mobile || coalesce(' · ' || upper(q.lead_temperature), ''), '/staff/quotations/' || q.id
          from (select coalesce(q.follow_up_manager_id, q.assigned_sales_id) u) x where u is not null;
      update quotation_requests set follow_up_alerted_on = today where id = q.id;
      n_fu := n_fu + 1;
    end loop;
  end if;

  -- Customer payments past their due date: managers, then again weekly
  for q in select pp.*, p.customer_name, p.job_number from project_payments pp join projects p on p.id = pp.project_id
            where pp.status in ('pending', 'partial', 'overdue') and pp.due_date < today
              and (pp.alerted_at is null or pp.alerted_at < now() - interval '7 days') loop
    perform notify_managers('payment', 'Payment overdue', coalesce(q.job_number, '') || ' · ' || coalesce(q.customer_name, '') || ' · ₹' ||
              round(q.amount - coalesce(q.amount_received, 0)) || ' (' || q.milestone_name || ') due ' || to_char(q.due_date, 'DD Mon'),
              '/staff/projects/' || q.project_id);
    update project_payments set alerted_at = now() where id = q.id;
    n_pay := n_pay + 1;
  end loop;

  if to_regproc('run_service_alerts') is not null then execute 'select run_service_alerts()' into n_svc; end if;
  return jsonb_build_object('leads', n_lead, 'follow_ups', n_fu, 'payments', n_pay, 'service', n_svc);
end;$$;
revoke all on function run_scheduled_alerts() from public, anon;
grant execute on function run_scheduled_alerts() to authenticated;

-- Every 15 minutes in the background, if pg_cron is available (Supabase: Database → Extensions).
-- Without it, alerts still run each time a manager opens the Control room or the dashboard.
do $$
begin
  begin
    create extension if not exists pg_cron;
  exception when others then
    raise notice 'pg_cron is not available here; alerts run when the Control room or dashboard is opened.';
  end;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('greenergy-alerts', '*/15 * * * *', 'select public.run_scheduled_alerts()');
  end if;
exception when others then
  raise notice 'Could not schedule the alerts job: %', sqlerrm;
end $$;


-- ┌───────────────────────────────────────────────────────────────
-- │ service_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Service v1 (27 Nov 2026): earn from the systems already installed.
--  * Maintenance contracts (AMC): numbered GSS/AMC/2026-27/0001, yearly fee, visits per year.
--    Creating one schedules its visits as service tickets; renewal is reminded 30 days before expiry.
--  * Service tickets: GSS/SR/2026-27/0001 for breakdowns, cleaning, inspections and AMC visits,
--    with a due date (by priority), the technician, the resolution and an optional charge.
--  * Service invoices: GSS/SI/2026-27/0001 (one series, gap-free), for a chargeable ticket or an AMC fee.
--  * O&M clock-ins can name the ticket: the hours spent on each job are known (billable vs not).
-- Needs growth_v1.sql (alerts) and attendance_multi_v1.sql first. Safe to run more than once.

create table if not exists service_contracts (
  id                 uuid default gen_random_uuid() primary key,
  contract_number    text unique,
  project_id         uuid references projects(id) on delete set null,
  customer_name      text not null check (char_length(customer_name) between 1 and 120),
  customer_mobile    text,
  site_address       text,
  region             text not null default 'puducherry' check (region in ('puducherry', 'tamilnadu')),
  capacity_kw        numeric,
  plan               text not null default 'Standard',
  visits_per_year    integer not null default 2 check (visits_per_year between 1 and 12),
  includes_cleaning  boolean not null default true,
  start_date         date not null,
  end_date           date not null,
  fee                numeric not null default 0 check (fee >= 0),     -- per contract, before GST
  gst_pct            numeric not null default 18 check (gst_pct between 0 and 28),
  status             text not null default 'active' check (status in ('active', 'expired', 'cancelled')),
  invoice_number     text unique,
  invoiced_at        timestamptz,
  paid_at            date,
  payment_mode       text,
  payment_ref        text,
  renewal_alerted_at timestamptz,
  renewed_to         uuid references service_contracts(id) on delete set null,
  notes              text,
  created_by         uuid references profiles(id) on delete set null default auth.uid(),
  created_at         timestamptz not null default now(),
  check (end_date > start_date)
);

create table if not exists service_tickets (
  id               uuid default gen_random_uuid() primary key,
  ticket_number    text unique,
  contract_id      uuid references service_contracts(id) on delete set null,
  project_id       uuid references projects(id) on delete set null,
  customer_name    text not null check (char_length(customer_name) between 1 and 120),
  customer_mobile  text,
  site_address     text,
  region           text not null default 'puducherry' check (region in ('puducherry', 'tamilnadu')),
  kind             text not null default 'breakdown' check (kind in ('amc_visit', 'breakdown', 'cleaning', 'inspection', 'installation_fix', 'other')),
  priority         text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  description      text not null check (char_length(description) between 1 and 2000),
  status           text not null default 'open' check (status in ('open', 'assigned', 'in_progress', 'resolved', 'closed', 'cancelled')),
  assigned_to      uuid references profiles(id) on delete set null,
  scheduled_for    date,
  due_date         date,
  resolved_at      timestamptz,
  resolution_notes text,
  chargeable       boolean not null default false,
  charge_amount    numeric not null default 0 check (charge_amount >= 0),   -- before GST
  gst_pct          numeric not null default 18 check (gst_pct between 0 and 28),
  invoice_number   text unique,
  invoiced_at      timestamptz,
  paid_at          date,
  payment_mode     text,
  payment_ref      text,
  alerted_on       date,
  created_by       uuid references profiles(id) on delete set null default auth.uid(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists service_tickets_open on service_tickets (status, due_date);
create index if not exists service_tickets_assignee on service_tickets (assigned_to, status);

alter table service_contracts enable row level security;
alter table service_tickets   enable row level security;
drop policy if exists "managers_contracts" on service_contracts;
create policy "managers_contracts" on service_contracts for select using (is_manager());
drop policy if exists "managers_add_contracts" on service_contracts;
create policy "managers_add_contracts" on service_contracts for insert with check (is_manager());
drop policy if exists "managers_edit_contracts" on service_contracts;
create policy "managers_edit_contracts" on service_contracts for update using (is_manager()) with check (is_manager());
drop policy if exists "ceo_delete_contracts" on service_contracts;
create policy "ceo_delete_contracts" on service_contracts for delete using (is_admin());

drop policy if exists "view_tickets" on service_tickets;
create policy "view_tickets" on service_tickets for select using (is_manager() or (assigned_to = auth.uid() and is_staff()));
drop policy if exists "add_tickets" on service_tickets;
create policy "add_tickets" on service_tickets for insert with check (is_staff());
drop policy if exists "edit_tickets" on service_tickets;
create policy "edit_tickets" on service_tickets for update using (is_manager() or (assigned_to = auth.uid() and is_staff()))
  with check (is_manager() or assigned_to = auth.uid());
drop policy if exists "ceo_delete_tickets" on service_tickets;
create policy "ceo_delete_tickets" on service_tickets for delete using (is_admin());

-- Numbers, defaults and who may change what
create or replace function service_contract_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.contract_number := next_doc_number('AMC');
    new.invoice_number := null; new.invoiced_at := null; new.renewed_to := null;
  elsif new.contract_number is distinct from old.contract_number
     or (new.invoice_number is distinct from old.invoice_number and coalesce(current_setting('greenergy.invoicing', true), '') <> 'on') then
    raise exception 'Contract and invoice numbers are issued by the CRM and cannot be changed.';
  elsif old.invoice_number is not null and auth.uid() is not null
     and (new.fee, new.gst_pct, new.customer_name, new.region) is distinct from (old.fee, old.gst_pct, old.customer_name, old.region) then
    raise exception 'This contract is invoiced: fee, GST, customer and state are fixed.';
  end if;
  return new;
end;$$;
drop trigger if exists trg_service_contract_guard on service_contracts;
create trigger trg_service_contract_guard before insert or update on service_contracts
  for each row execute function service_contract_guard();

create or replace function service_ticket_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare mgr boolean := auth.uid() is null or is_manager(); today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if tg_op = 'INSERT' then
    new.ticket_number := next_doc_number('SR');
    new.invoice_number := null; new.invoiced_at := null; new.paid_at := null;
    if not mgr then new.assigned_to := null; new.status := 'open'; new.chargeable := false; new.charge_amount := 0; end if;
    new.created_by := coalesce(auth.uid(), new.created_by);
    if new.assigned_to is not null and new.status = 'open' then new.status := 'assigned'; end if;
    new.due_date := coalesce(new.due_date, new.scheduled_for + 7,
      today + case new.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 7 end);
    return new;
  end if;
  if new.ticket_number is distinct from old.ticket_number
     or (new.invoice_number is distinct from old.invoice_number and coalesce(current_setting('greenergy.invoicing', true), '') <> 'on') then
    raise exception 'Ticket and invoice numbers are issued by the CRM and cannot be changed.';
  end if;
  if old.invoice_number is not null and auth.uid() is not null
     and (new.charge_amount, new.gst_pct, new.chargeable, new.customer_name, new.region) is distinct from (old.charge_amount, old.gst_pct, old.chargeable, old.customer_name, old.region) then
    raise exception 'This ticket is invoiced: the charge, customer and state are fixed.';
  end if;
  if not mgr then
    -- The technician: progress, resolution notes and closing the job only
    if (to_jsonb(new) - array['status', 'resolution_notes', 'resolved_at', 'updated_at'])
       is distinct from (to_jsonb(old) - array['status', 'resolution_notes', 'resolved_at', 'updated_at']) then
      raise exception 'You can update the progress and the resolution. The admin manager changes the rest.';
    end if;
    if new.status is distinct from old.status and new.status not in ('in_progress', 'resolved') then
      raise exception 'You can mark the job in progress or resolved.';
    end if;
  end if;
  if new.status = 'resolved' and old.status <> 'resolved' then
    if coalesce(trim(new.resolution_notes), '') = '' then raise exception 'Write what was done before marking it resolved.'; end if;
    new.resolved_at := coalesce(new.resolved_at, now());
  end if;
  if new.assigned_to is not null and new.assigned_to is distinct from old.assigned_to and new.status = 'open' then new.status := 'assigned'; end if;
  new.updated_at := now();
  return new;
end;$$;
drop trigger if exists trg_service_ticket_guard on service_tickets;
create trigger trg_service_ticket_guard before insert or update on service_tickets
  for each row execute function service_ticket_guard();

create or replace function service_ticket_notify()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.assigned_to is not null and new.assigned_to is distinct from auth.uid()
     and (tg_op = 'INSERT' or new.assigned_to is distinct from old.assigned_to) then
    insert into notifications (user_id, type, title, message, link) values (new.assigned_to, 'service', 'Service job given to you',
      new.ticket_number || ' · ' || new.customer_name || coalesce(' · ' || new.customer_mobile, '') || ' · due ' || to_char(new.due_date, 'DD Mon'),
      '/staff/service/' || new.id);
  end if;
  if tg_op = 'INSERT' and new.kind = 'breakdown' and new.assigned_to is null then
    perform notify_managers('service', 'New breakdown — assign a technician', new.ticket_number || ' · ' || new.customer_name, '/staff/service/' || new.id);
  end if;
  if tg_op = 'UPDATE' and new.status = 'resolved' and old.status <> 'resolved' then
    perform notify_managers('service', 'Service job resolved' || case when new.chargeable and new.invoice_number is null then ' — send the invoice' else '' end,
      new.ticket_number || ' · ' || new.customer_name, '/staff/service/' || new.id);
  end if;
  return new;
end;$$;
drop trigger if exists trg_service_ticket_notify on service_tickets;
create trigger trg_service_ticket_notify after insert or update on service_tickets
  for each row execute function service_ticket_notify();

-- A new contract books its visits, spread across the year
create or replace function service_contract_visits()
returns trigger language plpgsql security definer set search_path = public as $$
declare i int; d date; days int := new.end_date - new.start_date;
begin
  for i in 0 .. new.visits_per_year - 1 loop
    d := new.start_date + round((i + 0.5) * days / new.visits_per_year)::int;
    insert into service_tickets (contract_id, project_id, customer_name, customer_mobile, site_address, region, kind, priority,
                                 description, scheduled_for, due_date)
    values (new.id, new.project_id, new.customer_name, new.customer_mobile, new.site_address, new.region, 'amc_visit', 'normal',
            'AMC visit ' || (i + 1) || ' of ' || new.visits_per_year || ' (' || new.contract_number || '): '
              || case when new.includes_cleaning then 'panel cleaning, ' else '' end
              || 'visual inspection, torque check, IR / earth test, inverter log check.',
            d, d + 7);
  end loop;
  return new;
end;$$;
drop trigger if exists trg_service_contract_visits on service_contracts;
create trigger trg_service_contract_visits after insert on service_contracts
  for each row execute function service_contract_visits();

-- Renew: same terms for the next period
create or replace function renew_amc_contract(p_contract uuid, p_fee numeric default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare c service_contracts%rowtype; new_id uuid;
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager can renew a contract.'; end if;
  select * into c from service_contracts where id = p_contract for update;
  if not found then raise exception 'Contract not found.'; end if;
  if c.renewed_to is not null then raise exception 'Already renewed.'; end if;
  insert into service_contracts (project_id, customer_name, customer_mobile, site_address, region, capacity_kw, plan,
                                 visits_per_year, includes_cleaning, start_date, end_date, fee, gst_pct, notes)
  values (c.project_id, c.customer_name, c.customer_mobile, c.site_address, c.region, c.capacity_kw, c.plan,
          c.visits_per_year, c.includes_cleaning, c.end_date + 1, c.end_date + 1 + (c.end_date - c.start_date),
          coalesce(p_fee, c.fee), c.gst_pct, 'Renewal of ' || c.contract_number)
  returning id into new_id;
  update service_contracts set renewed_to = new_id where id = c.id;
  return new_id;
end;$$;

-- Invoice numbers: one gap-free series for service work and AMC fees
create or replace function issue_service_invoice(p_kind text, p_id uuid)
returns text language plpgsql security definer set search_path = public as $$
declare t service_tickets%rowtype; c service_contracts%rowtype; num text;
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager issues invoices.'; end if;
  perform set_config('greenergy.invoicing', 'on', true);
  if p_kind = 'ticket' then
    select * into t from service_tickets where id = p_id for update;
    if not found then raise exception 'Ticket not found.'; end if;
    if t.invoice_number is not null then return t.invoice_number; end if;
    if not t.chargeable or t.charge_amount <= 0 then raise exception 'Mark the job chargeable and enter the amount first.'; end if;
    if t.status not in ('resolved', 'closed') then raise exception 'Invoice after the job is resolved.'; end if;
    num := next_doc_number('SI');
    update service_tickets set invoice_number = num, invoiced_at = now() where id = p_id;
  elsif p_kind = 'amc' then
    select * into c from service_contracts where id = p_id for update;
    if not found then raise exception 'Contract not found.'; end if;
    if c.invoice_number is not null then return c.invoice_number; end if;
    if c.fee <= 0 then raise exception 'Enter the contract fee first.'; end if;
    num := next_doc_number('SI');
    update service_contracts set invoice_number = num, invoiced_at = now() where id = p_id;
  else
    raise exception 'Unknown invoice type.';
  end if;
  perform set_config('greenergy.invoicing', 'off', true);
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'service_invoice_issued', case when p_kind = 'ticket' then 'service_tickets' else 'service_contracts' end, p_id, num);
  return num;
end;$$;

create or replace function record_service_payment(p_kind text, p_id uuid, p_mode text, p_ref text, p_date date)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager records payments.'; end if;
  if p_date is null or p_date > (now() at time zone 'Asia/Kolkata')::date then raise exception 'Choose the date the money was received.'; end if;
  if p_kind = 'ticket' then
    update service_tickets set paid_at = p_date, payment_mode = left(p_mode, 20), payment_ref = left(p_ref, 120),
           status = case when status = 'resolved' then 'closed' else status end
     where id = p_id and invoice_number is not null;
  elsif p_kind = 'amc' then
    update service_contracts set paid_at = p_date, payment_mode = left(p_mode, 20), payment_ref = left(p_ref, 120)
     where id = p_id and invoice_number is not null;
  else raise exception 'Unknown type.';
  end if;
  if not found then raise exception 'Issue the invoice first.'; end if;
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'service_payment_recorded', p_kind, p_id, coalesce(p_mode, '') || ' ' || coalesce(p_ref, ''));
end;$$;

revoke all on function renew_amc_contract(uuid, numeric), issue_service_invoice(text, uuid),
  record_service_payment(text, uuid, text, text, date) from public, anon;
grant execute on function renew_amc_contract(uuid, numeric), issue_service_invoice(text, uuid),
  record_service_payment(text, uuid, text, text, date) to authenticated;

-- Service alerts (called by run_scheduled_alerts)
create or replace function run_service_alerts()
returns jsonb language plpgsql security definer set search_path = public as $$
declare t record; today date := (now() at time zone 'Asia/Kolkata')::date; n_visit int := 0; n_late int := 0; n_renew int := 0;
begin
  update service_contracts set status = 'expired' where status = 'active' and end_date < today;
  for t in select * from service_tickets where kind = 'amc_visit' and status = 'open' and assigned_to is null
            and scheduled_for <= today + 7 and alerted_on is null loop
    perform notify_managers('service', 'AMC visit to assign', t.ticket_number || ' · ' || t.customer_name || ' · ' || to_char(t.scheduled_for, 'DD Mon'),
                            '/staff/service/' || t.id);
    update service_tickets set alerted_on = today where id = t.id;
    n_visit := n_visit + 1;
  end loop;
  for t in select * from service_tickets where status in ('open', 'assigned', 'in_progress') and due_date < today
            and alerted_on is distinct from today loop
    perform notify_managers('service', 'Service job overdue', t.ticket_number || ' · ' || t.customer_name || ' · due ' || to_char(t.due_date, 'DD Mon'),
                            '/staff/service/' || t.id, array[t.assigned_to]);
    update service_tickets set alerted_on = today where id = t.id;
    n_late := n_late + 1;
  end loop;
  for t in select * from service_contracts where status = 'active' and renewed_to is null and renewal_alerted_at is null
            and end_date <= today + 30 loop
    perform notify_managers('service', 'AMC ends soon — offer the renewal', t.contract_number || ' · ' || t.customer_name || ' · ends ' || to_char(t.end_date, 'DD Mon YYYY'),
                            '/staff/service?tab=amc');
    update service_contracts set renewal_alerted_at = now() where id = t.id;
    n_renew := n_renew + 1;
  end loop;
  return jsonb_build_object('amc_visits', n_visit, 'overdue', n_late, 'renewals', n_renew);
end;$$;
revoke all on function run_service_alerts() from public, anon, authenticated;

-- ═══ Attendance: an O&M session can name the service job ═══
alter table attendance add column if not exists service_ticket_id uuid references service_tickets(id) on delete set null;

create or replace function attendance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  ceo     boolean := auth.uid() is null or is_admin();
  office  office_locations%rowtype;
  dist    double precision;
  slack   double precision;
  others  numeric;
begin
  if tg_op = 'INSERT' then
    if not ceo then
      new.date           := (now() at time zone 'Asia/Kolkata')::date;
      new.clock_in_time  := now();
      new.clock_out_time := null; new.clock_out_lat := null; new.clock_out_lng := null;
      new.total_hours    := null; new.overtime_hours := 0;
      new.attendance_status := 'present';
      new.is_location_mismatch := false;
    end if;
    new.session_no := coalesce((select max(session_no) from attendance
                                where employee_id = new.employee_id and date = new.date), 0) + 1;

    if new.work_type = 'office' then
      new.project_id := null; new.service_ticket_id := null;
      if new.clock_in_lat is null or new.clock_in_lng is null then
        raise exception 'Your location is needed to clock in at the office.';
      end if;
      select * into office from office_locations where active
        order by geo_distance_m(lat, lng, new.clock_in_lat::float8, new.clock_in_lng::float8) limit 1;
      if not found then
        raise exception 'The office location has not been set yet. Ask the CEO to set it in Attendance → Office location.';
      end if;
      dist := geo_distance_m(office.lat, office.lng, new.clock_in_lat::float8, new.clock_in_lng::float8);
      new.office_location_id  := office.id;
      new.clock_in_distance_m := round(dist::numeric);
      slack := least(coalesce(new.clock_in_accuracy_m::float8, 0), 100);
      if dist > office.radius_m + slack and not ceo then
        raise exception 'You are about % m from %. Office clock-in works within % m. Go to the office (or near a window / outside for a better GPS signal) and try again.',
          round(dist::numeric), office.name, office.radius_m;
      end if;
    elsif new.project_id is null and new.service_ticket_id is null and not ceo then
      raise exception 'Choose the project / site or the service job you are working on.';
    end if;
    return new;
  end if;

  if not ceo then
    if old.clock_out_time is not null then
      raise exception 'This session is already clocked out.';
    end if;
    new.employee_id := old.employee_id; new.date := old.date; new.session_no := old.session_no; new.work_type := old.work_type;
    new.project_id := old.project_id; new.service_ticket_id := old.service_ticket_id; new.office_location_id := old.office_location_id;
    new.clock_in_time := old.clock_in_time; new.clock_in_lat := old.clock_in_lat; new.clock_in_lng := old.clock_in_lng;
    new.clock_in_address := old.clock_in_address; new.clock_in_accuracy_m := old.clock_in_accuracy_m;
    new.clock_in_distance_m := old.clock_in_distance_m; new.attendance_status := old.attendance_status;
    if new.clock_out_time is not null then new.clock_out_time := now(); end if;
  end if;

  if new.clock_out_time is not null and new.work_type = 'office' and new.clock_out_lat is not null and new.clock_out_lng is not null then
    select * into office from office_locations where id = new.office_location_id;
    if found then
      dist := geo_distance_m(office.lat, office.lng, new.clock_out_lat::float8, new.clock_out_lng::float8);
      new.clock_out_distance_m := round(dist::numeric);
      new.is_location_mismatch := dist > office.radius_m + least(coalesce(new.clock_out_accuracy_m::float8, 0), 100);
    end if;
  end if;

  if new.clock_out_time is not null and new.clock_in_time is not null then
    new.total_hours := round((extract(epoch from new.clock_out_time - new.clock_in_time) / 3600)::numeric, 2);
    select coalesce(sum(total_hours), 0) into others from attendance
      where employee_id = new.employee_id and date = new.date and id <> new.id and total_hours is not null;
    new.overtime_hours := greatest(0, others + new.total_hours - 8) - greatest(0, others - 8);
  else
    new.total_hours := null; new.overtime_hours := 0;
  end if;
  return new;
end;$$;

-- Clock-in now takes an optional service job (p_ticket). The old 8-argument version is replaced.
drop function if exists attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text);
create or replace function attendance_clock_in(
  p_device uuid, p_secret text, p_work_type text, p_project uuid,
  p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text, p_ticket uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare dev uuid; new_id uuid; mode text; open_rec attendance%rowtype; tk service_tickets%rowtype;
        today date := (now() at time zone 'Asia/Kolkata')::date; proj uuid := p_project;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if is_admin() then raise exception 'The CEO does not clock in or out.'; end if;
  dev := _check_attendance_device(p_device, p_secret);
  perform pg_advisory_xact_lock(hashtext('attendance:' || auth.uid()::text));

  select coalesce(attendance_mode, 'office') into mode from profiles where id = auth.uid();
  select * into open_rec from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time > now() - interval '18 hours'
    order by clock_in_time desc limit 1;
  if found then
    raise exception 'You are still clocked in since % (session %). Clock out first.',
      to_char(open_rec.clock_in_time at time zone 'Asia/Kolkata', 'HH12:MI AM'), open_rec.session_no;
  end if;
  if mode = 'office' and exists (select 1 from attendance where employee_id = auth.uid() and date = today) then
    raise exception 'You have already clocked in today. (Office attendance is once a day; ask the CEO if you need several sessions for site work.)';
  end if;
  if (select count(*) from attendance where employee_id = auth.uid() and date = today) >= 12 then
    raise exception 'That is 12 sessions today already. Ask the CEO to correct your attendance.';
  end if;
  if p_ticket is not null then
    select * into tk from service_tickets where id = p_ticket;
    if not found or (tk.assigned_to is distinct from auth.uid() and not is_manager()) then
      raise exception 'That service job is not given to you.';
    end if;
    if tk.status in ('resolved', 'closed', 'cancelled') then raise exception 'That service job is already finished.'; end if;
    proj := coalesce(tk.project_id, p_project);
  elsif p_work_type = 'site' and p_project is not null and not is_manager() and not exists (
    select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null) then
    raise exception 'You are not assigned to that project.';
  end if;
  insert into attendance (employee_id, work_type, project_id, service_ticket_id, clock_in_lat, clock_in_lng, clock_in_accuracy_m, clock_in_address, device_id)
    values (auth.uid(), case when p_work_type = 'office' and p_ticket is null then 'office' else 'site' end, proj, p_ticket,
            p_lat, p_lng, p_accuracy, left(p_address, 500), dev)
    returning id into new_id;
  if p_ticket is not null and tk.status in ('open', 'assigned') then
    update service_tickets set status = 'in_progress' where id = p_ticket;
  end if;
  return new_id;
end;$$;
revoke all on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text, uuid) from public, anon;
grant execute on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text, uuid) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_outside_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance: "Out on work" sessions (27 Nov 2026)
-- For staff who move between the office, customer site visits, the EB office and other errands
-- in one day. Besides "office" (inside the office radius) and "site" (an assigned project or a
-- service job), a session can now be:
--   outside : away from the office on company work. The purpose is required:
--               site_visit (survey / meeting for a lead), eb_office (EB / net-meter follow-up),
--               purchase (supplier / material), bank_govt (bank or government office), other.
--             It can name the lead or project it was for. A short note (where / what) is
--             required when it names neither, or the purpose is "other".
--             GPS is recorded at clock-in and clock-out as always, but there is no radius check.
-- People who do this several times a day need the "field" attendance type (several sessions a day).
-- Needs attendance_multi_v1.sql and service_v1.sql first. Safe to run more than once.

alter table attendance drop constraint if exists attendance_work_type_check;
alter table attendance add constraint attendance_work_type_check check (work_type in ('office', 'site', 'outside'));
alter table attendance add column if not exists purpose text;
alter table attendance add column if not exists purpose_note text;
alter table attendance add column if not exists quotation_id uuid references quotation_requests(id) on delete set null;
alter table attendance drop constraint if exists attendance_purpose_check;
alter table attendance add constraint attendance_purpose_check
  check (purpose is null or purpose in ('site_visit', 'eb_office', 'purchase', 'bank_govt', 'other'));

create or replace function attendance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  ceo     boolean := auth.uid() is null or is_admin();
  office  office_locations%rowtype;
  dist    double precision;
  slack   double precision;
  others  numeric;
begin
  if tg_op = 'INSERT' then
    if not ceo then
      new.date           := (now() at time zone 'Asia/Kolkata')::date;
      new.clock_in_time  := now();
      new.clock_out_time := null; new.clock_out_lat := null; new.clock_out_lng := null;
      new.total_hours    := null; new.overtime_hours := 0;
      new.attendance_status := 'present';
      new.is_location_mismatch := false;
    end if;
    new.session_no := coalesce((select max(session_no) from attendance
                                where employee_id = new.employee_id and date = new.date), 0) + 1;

    if new.work_type = 'office' then
      new.project_id := null; new.service_ticket_id := null; new.quotation_id := null;
      new.purpose := null; new.purpose_note := null;
      if new.clock_in_lat is null or new.clock_in_lng is null then
        raise exception 'Your location is needed to clock in at the office.';
      end if;
      select * into office from office_locations where active
        order by geo_distance_m(lat, lng, new.clock_in_lat::float8, new.clock_in_lng::float8) limit 1;
      if not found then
        raise exception 'The office location has not been set yet. Ask the CEO to set it in Attendance → Office location.';
      end if;
      dist := geo_distance_m(office.lat, office.lng, new.clock_in_lat::float8, new.clock_in_lng::float8);
      new.office_location_id  := office.id;
      new.clock_in_distance_m := round(dist::numeric);
      slack := least(coalesce(new.clock_in_accuracy_m::float8, 0), 100);
      if dist > office.radius_m + slack and not ceo then
        raise exception 'You are about % m from %. Office clock-in works within % m. Go to the office (or near a window / outside for a better GPS signal) and try again.',
          round(dist::numeric), office.name, office.radius_m;
      end if;
    elsif new.work_type = 'outside' then
      new.service_ticket_id := null; new.office_location_id := null;
      new.purpose_note := nullif(btrim(left(new.purpose_note, 300)), '');
      if not ceo then
        if new.purpose is null then
          raise exception 'Choose what you are going out for (site visit, EB office, purchase, bank / govt office or other).';
        end if;
        if new.clock_in_lat is null or new.clock_in_lng is null then
          raise exception 'Your location is needed to clock in.';
        end if;
        if (new.purpose = 'other' or (new.quotation_id is null and new.project_id is null))
           and coalesce(length(new.purpose_note), 0) < 3 then
          raise exception 'Write where you are going and why (e.g. "EB office Lawspet – net meter file of Ravi").';
        end if;
      end if;
    else
      new.quotation_id := null; new.purpose := null; new.purpose_note := null;
      if new.project_id is null and new.service_ticket_id is null and not ceo then
        raise exception 'Choose the project / site or the service job you are working on.';
      end if;
    end if;
    return new;
  end if;

  if not ceo then
    if old.clock_out_time is not null then
      raise exception 'This session is already clocked out.';
    end if;
    new.employee_id := old.employee_id; new.date := old.date; new.session_no := old.session_no; new.work_type := old.work_type;
    new.project_id := old.project_id; new.service_ticket_id := old.service_ticket_id; new.office_location_id := old.office_location_id;
    new.quotation_id := old.quotation_id; new.purpose := old.purpose; new.purpose_note := old.purpose_note;
    new.clock_in_time := old.clock_in_time; new.clock_in_lat := old.clock_in_lat; new.clock_in_lng := old.clock_in_lng;
    new.clock_in_address := old.clock_in_address; new.clock_in_accuracy_m := old.clock_in_accuracy_m;
    new.clock_in_distance_m := old.clock_in_distance_m; new.attendance_status := old.attendance_status;
    if new.clock_out_time is not null then new.clock_out_time := now(); end if;
  end if;

  if new.clock_out_time is not null and new.work_type = 'office' and new.clock_out_lat is not null and new.clock_out_lng is not null then
    select * into office from office_locations where id = new.office_location_id;
    if found then
      dist := geo_distance_m(office.lat, office.lng, new.clock_out_lat::float8, new.clock_out_lng::float8);
      new.clock_out_distance_m := round(dist::numeric);
      new.is_location_mismatch := dist > office.radius_m + least(coalesce(new.clock_out_accuracy_m::float8, 0), 100);
    end if;
  end if;

  if new.clock_out_time is not null and new.clock_in_time is not null then
    new.total_hours := round((extract(epoch from new.clock_out_time - new.clock_in_time) / 3600)::numeric, 2);
    select coalesce(sum(total_hours), 0) into others from attendance
      where employee_id = new.employee_id and date = new.date and id <> new.id and total_hours is not null;
    new.overtime_hours := greatest(0, others + new.total_hours - 8) - greatest(0, others - 8);
  else
    new.total_hours := null; new.overtime_hours := 0;
  end if;
  return new;
end;$$;

-- Clock-in also takes the purpose, a note and a lead. The 9-argument version is replaced.
drop function if exists attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text, uuid);
create or replace function attendance_clock_in(
  p_device uuid, p_secret text, p_work_type text, p_project uuid,
  p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text,
  p_ticket uuid default null, p_purpose text default null, p_note text default null, p_quotation uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare dev uuid; new_id uuid; mode text; open_rec attendance%rowtype; tk service_tickets%rowtype;
        today date := (now() at time zone 'Asia/Kolkata')::date; proj uuid := p_project;
        wt text := case when p_work_type in ('office', 'outside') and p_ticket is null then p_work_type else 'site' end;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if is_admin() then raise exception 'The CEO does not clock in or out.'; end if;
  dev := _check_attendance_device(p_device, p_secret);
  perform pg_advisory_xact_lock(hashtext('attendance:' || auth.uid()::text));

  select coalesce(attendance_mode, 'office') into mode from profiles where id = auth.uid();
  select * into open_rec from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time > now() - interval '18 hours'
    order by clock_in_time desc limit 1;
  if found then
    raise exception 'You are still clocked in since % (session %). Clock out first.',
      to_char(open_rec.clock_in_time at time zone 'Asia/Kolkata', 'HH12:MI AM'), open_rec.session_no;
  end if;
  if mode = 'office' and exists (select 1 from attendance where employee_id = auth.uid() and date = today) then
    raise exception 'You have already clocked in today. (Office attendance is once a day; ask the CEO to set your attendance type to "Field" if you work in several places a day.)';
  end if;
  if (select count(*) from attendance where employee_id = auth.uid() and date = today) >= 12 then
    raise exception 'That is 12 sessions today already. Ask the CEO to correct your attendance.';
  end if;
  if p_ticket is not null then
    select * into tk from service_tickets where id = p_ticket;
    if not found or (tk.assigned_to is distinct from auth.uid() and not is_manager()) then
      raise exception 'That service job is not given to you.';
    end if;
    if tk.status in ('resolved', 'closed', 'cancelled') then raise exception 'That service job is already finished.'; end if;
    proj := coalesce(tk.project_id, p_project);
  elsif wt = 'outside' then
    -- Optional links: only to a lead or project this person can see
    if p_quotation is not null and not can_view_quotation(p_quotation) then
      raise exception 'That lead is not one of yours.';
    end if;
    if p_project is not null and not can_view_project(p_project) then
      raise exception 'That project is not one of yours.';
    end if;
  elsif wt = 'site' and p_project is not null and not is_manager() and not exists (
    select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null) then
    raise exception 'You are not assigned to that project.';
  end if;
  insert into attendance (employee_id, work_type, project_id, service_ticket_id, quotation_id, purpose, purpose_note,
                          clock_in_lat, clock_in_lng, clock_in_accuracy_m, clock_in_address, device_id)
    values (auth.uid(), wt, case when wt = 'office' then null else proj end, p_ticket,
            case when wt = 'outside' then p_quotation end, case when wt = 'outside' then p_purpose end,
            case when wt = 'outside' then p_note end,
            p_lat, p_lng, p_accuracy, left(p_address, 500), dev)
    returning id into new_id;
  if p_ticket is not null and tk.status in ('open', 'assigned') then
    update service_tickets set status = 'in_progress' where id = p_ticket;
  end if;
  return new_id;
end;$$;
revoke all on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text, uuid, text, text, uuid) from public, anon;
grant execute on function attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text, uuid, text, text, uuid) to authenticated;
